\label{lemma-strict-transform}
In the situation of Definition \ref{definition-strict-transform}.
\begin{enumerate}
\item The strict transform $X'$ of $X$ is the blowup of $X$ in the closed
subscheme $f^{-1}Z$ of $X$.
\item For a quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$ the
strict transform $\mathcal{F}'$ is canonically isomorphic to
the pushforward along $X' \to X \times_S S'$ of the strict transform of
$\mathcal{F}$ relative to the blowing up $X' \to X$.
\end{enumerate}

\label{lemma-extended-alternating-is-complex}
The extended alternating {\v C}ech complexes defined above
are complexes of $R$-modules.

\label{lemma-algebraic-center}
Let $k$ be a field. Let $G$ be a locally algebraic group scheme over $k$.
Then the center of $G$ is a closed subgroup scheme of $G$.

\label{lemma-existence-lower-shriek}
Let $\mathcal{C}$, $\mathcal{D}$ be two sites.
Let $f : \Sh(\mathcal{D}) \to \Sh(\mathcal{C})$ be a morphism of topoi.
Let $E \subset \Ob(\mathcal{D})$ be a subset such that
\begin{enumerate}
\item for $V \in E$ there exists a sheaf $\mathcal{G}$
on $\mathcal{C}$ such that $f^{-1}\mathcal{F}(V) = 
\Mor_{\Sh(\mathcal{C})}(\mathcal{G}, \mathcal{F})$ functorially
for $\mathcal{F}$ in $\Sh(\mathcal{C})$,
\item every object of $\mathcal{D}$ has a covering by objects of $E$.
\end{enumerate}
Then $f^{-1}$ has a left adjoint $f_!$.

\label{lemma-characterize-unramified-completions}
Let $A$, $B$ be Noetherian local rings.
Let $A \to B$ be a local homomorphism such that $B$ is
essentially of finite type over $A$.
The following are equivalent
\begin{enumerate}
\item $A \to B$ is an unramified homomorphism of local rings
\item $A^\wedge \to B^\wedge$ is an unramified homomorphism of local rings, and
\item $A^\wedge \to B^\wedge$ is unramified.
\end{enumerate}

\label{proposition-dim-1-noetherian-separated-has-ample}
Let $X$ be a Noetherian separated scheme of dimension $1$.
Then $X$ has an ample invertible sheaf.

\label{lemma-coequalizer-surjection}
Let $\mathcal{C}$ be a site. Let $\mathcal{F} \to \mathcal{G}$
be a surjection of sheaves of sets. Then the diagram
$$
\xymatrix{
\mathcal{F} \times_\mathcal{G} \mathcal{F}
\ar@<1ex>[r] \ar@<-1ex>[r]
&
\mathcal{F} \ar[r]
&
\mathcal{G}}
$$
represents $\mathcal{G}$ as a coequalizer.

\label{lemma-flat-base-change-blowing-up}
\begin{slogan}
Blowing up commutes with flat base change.
\end{slogan}
Let $X_1 \to X_2$ be a flat morphism of schemes. Let $Z_2 \subset X_2$ be a
closed subscheme. Let $Z_1$ be the inverse image of $Z_2$ in $X_1$.
Let $X'_i$ be the blowup of $Z_i$ in $X_i$. Then there exists a cartesian
diagram
$$
\xymatrix{
X_1' \ar[r] \ar[d] & X_2' \ar[d] \\
X_1 \ar[r] & X_2
}
$$
of schemes.

\label{lemma-flat-over-integral-integral-fibre}
Let $f : X \to Y$ be a flat morphism of schemes. If $Y$ is integral
and the generic fibre of $f$ is integral, then $X$ is integral.

\label{lemma-descending-property-quasi-separated}
The property $\mathcal{P}(f) =$``$f$ is quasi-separated''
is fpqc local on the base.

\label{lemma-extend-rational-map-after-modification}
Let $S$ be a scheme. Let $X$, $Y$ be schemes over $S$.
Assume $X$ is Noetherian and $Y$ is proper over $S$.
Given an $S$-rational map $f : U \to Y$ from $X$ to $Y$
there exists a morphism $p : X' \to X$ and an
$S$-morphism $f' : X' \to Y$ such that
\begin{enumerate}
\item $p$ is proper and $p^{-1}(U) \to U$ is an isomorphism,
\item $f'|_{p^{-1}(U)}$ is equal to $f \circ p|_{p^{-1}(U)}$.
\end{enumerate}

\label{lemma-check-reflexive}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
The following are equivalent:
\begin{enumerate}
\item $M$ is reflexive,
\item $M_\mathfrak p$ is a reflexive $R_\mathfrak p$-module
for all primes $\mathfrak p \subset R$, and
\item $M_\mathfrak m$ is a reflexive $R_\mathfrak m$-module
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}

\label{lemma-hom-into-S2}
Let $R$ be a Noetherian ring. Let $M$, $N$ be finite $R$-modules.
\begin{enumerate}
\item If $N$ has property $(S_1)$, then $\Hom_R(M, N)$ has property $(S_1)$.
\item If $N$ has property $(S_2)$, then $\Hom_R(M, N)$ has property $(S_2)$.
\item If $R$ is a domain, $N$ is torsion free and $(S_2)$, then
$\Hom_R(M, N)$ is torsion free and has property $(S_2)$.
\end{enumerate}

\label{lemma-faithful}
In the situation of Lemma \ref{lemma-pullback}
assume that $f : X' \to X$ is surjective
and flat. Then the pullback functor is faithful.

\label{lemma-descending-property-etale}
The property $\mathcal{P}(f) =$``$f$ is \'etale''
is fpqc local on the base.

\label{lemma-change-ideal-henselian-pair}
Let $A$ be a ring. Let $I, J \subset A$ be ideals with $V(I) = V(J)$.
Then $(A, I)$ is henselian if and only if $(A, J)$ is henselian.

\label{lemma-derived-limit-suitable-system}
Let $(X, \mathcal{O}_X)$ be a ringed space. Let $(K_n)$
be an inverse system of objects of $D(\mathcal{O}_X)$.
Let $\mathcal{B}$ be a set of opens of $X$. Assume
\begin{enumerate}
\item every open of $X$ has a covering whose members are
elements of $\mathcal{B}$,
\item for all $U \in \mathcal{B}$ and all $q \in \mathbf{Z}$ we have
\begin{enumerate}
\item $H^p(U, H^q(K_n)) = 0$ for $p > 0$,
\item the inverse system $H^0(U, H^q(K_n))$ has vanishing $R^1\lim$.
\end{enumerate}
\end{enumerate}
Then $H^q(R\lim K_n) = \lim H^q(K_n)$ for $q \in \mathbf{Z}$.

\label{lemma-check-reflexive-on-affines}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$ be a
coherent $\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item for $U \subset X$ affine open $\mathcal{F}(U)$
is a reflexive $\mathcal{O}(U)$-module.
\end{enumerate}

\label{lemma-composition-morphisms-sites}
\begin{slogan}
Composition of site functors respects continuity of site functors.
\end{slogan}
Let $\mathcal{C}_i$, $i = 1, 2, 3$ be sites. Let
$u : \mathcal{C}_2 \to \mathcal{C}_1$ and
$v : \mathcal{C}_3 \to \mathcal{C}_2$ be continuous functors
which induce morphisms of sites. Then the functor
$u \circ v : \mathcal{C}_3 \to \mathcal{C}_1$ is continuous and
defines a morphism of sites $\mathcal{C}_1 \to \mathcal{C}_3$.

\label{lemma-cartesian-equivalent-descent-datum}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of schemes over $S$.
The construction of Lemma \ref{lemma-characterize-cartesian-schemes}
determines an equivalence
$$
\begin{matrix}
\text{category of groupoid schemes} \\
\text{cartesian over } (X, X \times_Y X, \ldots)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } X/Y
\end{matrix}
$$

\label{lemma-absolutely-integrally-closed-strictly-henselian}
Let $A$ be absolutely integrally closed. Let $\mathfrak p \subset A$
be a prime. Then the local ring $A_\mathfrak p$ is strictly henselian.

\label{lemma-complement-affine-open-immersion}
\begin{reference}
\cite[EGA IV, Corollaire 21.12.7]{EGA4}
\end{reference}
Let $X$ be a locally Noetherian scheme. Let $U \subset X$ be an open subscheme
such that the inclusion morphism $U \to X$ is affine.
For every generic point $\xi$ of an irreducible component of
$X \setminus U$ the local ring $\mathcal{O}_{X, \xi}$
has dimension $\leq 1$. If $U$ is dense or if $\xi$ is in the closure
of $U$, then $\dim(\mathcal{O}_{X, \xi}) = 1$.

\label{lemma-CM-goes-up}
Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is regular,
\item $S$ is Noetherian, and
\item $R$ is Noetherian and Cohen-Macaulay.
\end{enumerate}
Then $S$ is Cohen-Macaulay.

\label{lemma-general-degree-g-line-bundle}
Let $k$ be an algebraically closed field. Let $X$ be a proper curve over $k$.
Then there exist
\begin{enumerate}
\item an invertible $\mathcal{O}_X$-module $\mathcal{L}$ with
$\dim_k H^0(X, \mathcal{L}) = 1$ and $H^1(X, \mathcal{L}) = 0$, and
\item an invertible $\mathcal{O}_X$-module $\mathcal{N}$ with
$\dim_k H^0(X, \mathcal{N}) = 0$ and $H^1(X, \mathcal{N}) = 0$.
\end{enumerate}

\label{lemma-sum-henselian}
Let $A$ be a ring and let $(A, I)$ and $(A, I')$ be henselian pairs.
Then $(A, I + I')$ is an henselian pair.

\label{lemma-projectors-have-images}
Let $\mathcal{D}$ be a preadditive category.
\begin{enumerate}
\item If $\mathcal{D}$ has countable products and kernels of maps which
have a right inverse, then $\mathcal{D}$ is Karoubian.
\item If $\mathcal{D}$ has countable coproducts and cokernels of
maps which have a left inverse, then $\mathcal{D}$ is Karoubian.
\end{enumerate}

\label{lemma-content-exists-flat-Mittag-Leffler}
Let $A$ be a ring. Let $M$ be a flat Mittag-Leffler module.
Then every element of $M$ has a content ideal.

\label{lemma-symmetric-algebra-smooth}
Let $A$ be a ring. Let $M$ be an $A$-module. Then $C = \text{Sym}_A^*(M)$
is smooth over $A$ if and only if $M$ is a finite projective $A$-module.

\label{lemma-generically-etale}
\begin{slogan}
A morphism of smooth curves is separable iff it is etale almost everywhere
\end{slogan}
Let $k$ be a field. Let $f : X \to Y$ be a morphism of smooth curves over $k$.
The following are equivalent
\begin{enumerate}
\item $\text{d}f : f^*\Omega_{Y/k} \to \Omega_{X/k}$ is nonzero,
\item $\Omega_{X/Y}$ is supported on a proper closed subset of $X$,
\item there exists a nonempty open $U \subset X$ such that
$f|_U : U \to Y$ is unramified,
\item there exists a nonempty open $U \subset X$ such that
$f|_U : U \to Y$ is \'etale,
\item the extension $k(X)/k(Y)$ of function fields is
finite separable.
\end{enumerate}

\label{lemma-flat-universally-injective}
Let $f : X \to Y$ be a morphism of schemes. Let $X^0$ denote the set
of generic points of irreducible components of $X$. If
\begin{enumerate}
\item $f$ is flat and separated,
\item for $\xi \in X^0$ we have $\kappa(f(\xi)) = \kappa(\xi)$, and
\item if $\xi, \xi' \in X^0$, $\xi \not = \xi'$, then $f(\xi) \not = f(\xi')$,
\end{enumerate}
then $f$ is universally injective.

\label{lemma-characterize-OD}
\begin{slogan}
Effective Cartier divisors on a scheme are the same as invertible sheaves
with fixed regular global section.
\end{slogan}
Let $X$ be a scheme.
\begin{enumerate}
\item If $D \subset X$ is an effective Cartier divisor, then
the canonical section $1_D$ of $\mathcal{O}_X(D)$ is regular.
\item Conversely, if $s$ is a regular section of the invertible
sheaf $\mathcal{L}$, then there exists a unique effective
Cartier divisor $D = Z(s) \subset X$ and a unique isomorphism
$\mathcal{O}_X(D) \to \mathcal{L}$ which maps $1_D$ to $s$.
\end{enumerate}
The constructions
$D \mapsto (\mathcal{O}_X(D), 1_D)$ and $(\mathcal{L}, s) \mapsto Z(s)$
give mutually inverse maps
$$
\left\{
\begin{matrix}
\text{effective Cartier divisors on }X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{isomorphism classes of pairs }(\mathcal{L}, s)\\
\text{consisting of an invertible }
\mathcal{O}_X\text{-module}\\
\mathcal{L}\text{ and a regular global section }s
\end{matrix}
\right\}
$$

\label{lemma-syntomic-lci}
Let $R \to S$ be a ring map. The following are equivalent
\begin{enumerate}
\item $R \to S$ is syntomic
(Algebra, Definition \ref{algebra-definition-lci}), and
\item $R \to S$ is flat and a local complete intersection.
\end{enumerate}

\label{lemma-descending-property-universally-open}
The property $\mathcal{P}(f) =$``$f$ is universally open''
is fpqc local on the base.

\label{proposition-point-limits}
Let $\mathcal{C}$ be a site. Assume that finite limits exist
in $\mathcal{C}$. (I.e., $\mathcal{C}$ has fibre products, and a
final object.) A point $p$ of such a site $\mathcal{C}$
is given by a functor $u : \mathcal{C} \to \textit{Sets}$ such that
\begin{enumerate}
\item $u$ commutes with finite limits, and
\item if $\{U_i \to U\}$ is a covering, then
$\coprod_i u(U_i) \to u(U)$ is surjective.
\end{enumerate}

\label{lemma-g1d}
Let $k$ be a field. Let $X$ be a nonsingular proper curve over $k$.
Let $(\mathcal{L}, V)$ be a $\mathfrak g^1_d$ on $X$. Then the morphism
$\varphi : X \to \mathbf{P}^1_k$ of Lemma \ref{lemma-linear-series}
either
\begin{enumerate}
\item is nonconstant and has degree $\leq d$, or
\item factors through a closed point of $\mathbf{P}^1_k$ and in this
case $H^0(X, \mathcal{O}_X) \not = k$.
\end{enumerate}

\label{lemma-etale-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is \'etale''
is \'etale local on the source.

\label{lemma-normal-local-smooth}
\begin{slogan}
Normality is local in the smooth topology.
\end{slogan}
The property $\mathcal{P}(S) =$``$S$ is normal'' is local in the smooth
topology.

\label{lemma-irreducible-group-scheme-over-field-qc}
Let $G$ be a group scheme over a field $k$. If $G$ is irreducible,
then $G$ is quasi-compact.

\label{lemma-absolutely-integrally-closed}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item $A$ is absolutely integrally closed, and
\item any monic $f \in A[T]$ has a root in $A$.
\end{enumerate}

\label{lemma-irreducible-henselian-pair-connected}
Let $(A, I)$ be a henselian pair. Let $\mathfrak p \subset A$
be a prime ideal. Then $V(\mathfrak p + I)$ is connected.

\label{lemma-reduced-goes-up}
Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is regular,
\item $S$ is Noetherian, and
\item $R$ is Noetherian and reduced.
\end{enumerate}
Then $S$ is reduced.

\label{lemma-algebraic-quasi-projective}
Let $k$ be a field. Let $G$ be an algebraic group scheme over $k$.
Then $G$ is quasi-projective over $k$.

\label{lemma-normal-domain-absolutely-integrally-closed}
Let $A$ be a normal domain. Then $A$ is absolutely integrally closed
if and only if its fraction field is algebraically closed.

\label{lemma-immersion-regular-regular-immersion}
Let $i : Z \to X$ be an immersion. If $Z$ and $X$ are
regular schemes, then $i$ is a regular immersion.

\label{lemma-fitting-ideal-finite-locally-free}
Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type, quasi-coherent
$\mathcal{O}_S$-module. Let $r \geq 0$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is finite locally free of rank $r$
\item $\text{Fit}_{r - 1}(\mathcal{F}) = 0$ and
$\text{Fit}_r(\mathcal{F}) = \mathcal{O}_S$, and
\item $\text{Fit}_k(\mathcal{F}) = 0$ for $k < r$ and
$\text{Fit}_k(\mathcal{F}) = \mathcal{O}_S$ for $k \geq r$.
\end{enumerate}

\label{lemma-locally-free-rank-r-pullback}
Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type, quasi-coherent
$\mathcal{O}_S$-module. The closed subschemes
$$
S = Z_{-1} \supset Z_0 \supset Z_1 \supset Z_2 \ldots
$$
defined by the Fitting ideals of $\mathcal{F}$ have the following
properties
\begin{enumerate}
\item The intersection $\bigcap Z_r$ is empty.
\item The functor $(\Sch/S)^{opp} \to \textit{Sets}$ defined by the rule
$$
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ is locally generated by }
\leq r\text{ sections} \\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
is representable by the open subscheme $S \setminus Z_r$.
\item The functor $F_r : (\Sch/S)^{opp} \to \textit{Sets}$ defined by the rule
$$
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ locally free rank }r\\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
is representable by the locally closed subscheme $Z_{r - 1} \setminus Z_r$
of $S$.
\end{enumerate}
If $\mathcal{F}$ is of finite presentation, then
$Z_r \to S$, $S \setminus Z_r \to S$, and $Z_{r - 1} \setminus Z_r \to S$
are of finite presentation.

\label{lemma-adjoint-preserve-K-injectives}
Let $\mathcal{A}$ and $\mathcal{B}$ be abelian categories.
Let $u : \mathcal{A} \to \mathcal{B}$ and
$v : \mathcal{B} \to \mathcal{A}$ be additive functors. Assume
\begin{enumerate}
\item $u$ is right adjoint to $v$, and
\item $v$ is exact.
\end{enumerate}
Then $u$ transforms K-injective complexes into K-injective complexes.

\label{theorem-glueing-bbd-general}
\begin{reference}
Special case of \cite[Theorem 3.2.4]{BBD}
without boundedness assumption.
\end{reference}
In Situation \ref{situation-locally-given} assume
\begin{enumerate}
\item $X = \bigcup_{U \in \mathcal{B}} U$,
\item for $U, V \in \mathcal{B}$ we have
$U \cap V = \bigcup_{W \in \mathcal{B}, W \subset U \cap V} W$,
\item for any $U \in \mathcal{B}$ we have $\Ext^i(K_U, K_U) = 0$
for $i < 0$.
\end{enumerate}
Then there exists an object $K$ of $D(\mathcal{O}_X)$
and isomorphisms $\rho_U : K|_U \to K_U$ in $D(\mathcal{O}_U)$ for
$U \in \mathcal{B}$ such that $\rho^U_V \circ \rho_U|_V = \rho_V$
for all $V \subset U$ with $U, V \in \mathcal{B}$.
The pair $(K, \rho_U)$ is unique up to unique isomorphism.

\label{lemma-nodal-family}
Let $f : X \to S$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is flat, locally of finite presentation, every nonempty fibre
$X_s$ is equidimensional of dimension $1$, and $X_s$ has
at-worst-nodal singularities, and
\item $f$ is syntomic of relative dimension $1$ and the closed subscheme
$\text{Sing}(f) \subset X$ defined by the first Fitting ideal of
$\Omega_{X/S}$ is unramified over $S$.
\end{enumerate}

\label{lemma-product-varieties}
\begin{slogan}
Products of varieties are varieties over algebraically closed fields.
\end{slogan}
Let $k$ be an algebraically closed field.
Let $X$, $Y$ be varieties over $k$.
Then $X \times_{\Spec(k)} Y$ is a variety over $k$.

\label{lemma-cohomology-bounded-below}
Let $\mathcal{A}$ be an abelian category.
Let $K^\bullet$ be a complex of $\mathcal{A}$.
\begin{enumerate}
\item If $K^\bullet$ has an injective resolution then
$H^n(K^\bullet) = 0$ for $n \ll 0$.
\item If $H^n(K^\bullet) = 0$ for all $n \ll 0$ then there
exists a quasi-isomorphism $K^\bullet \to L^\bullet$
with $L^\bullet$ bounded below.
\end{enumerate}

\label{lemma-curve-affine-projective}
Let $X$ be a curve over $k$. Then either $X$ is an affine scheme or $X$
is H-projective over $k$.

\label{lemma-geometrically-reduced-stein}
Let $k$ be a field. Let $X$ be a proper geometrically reduced scheme over $k$.
The following are equivalent
\begin{enumerate}
\item $H^0(X, \mathcal{O}_X) = k$, and
\item $X$ is geometrically connected.
\end{enumerate}

\label{lemma-group-scheme-over-field-open-multiplication}
If $(G, m)$ is a group scheme over a field $k$, then the
multiplication map $m : G \times_k G \to G$ is open.

\label{theorem-remarkable-equivalence}
\begin{reference}
\cite[IV, Theorem 18.1.2]{EGA}
\end{reference}
Let $S$ be a scheme.
Let $S_0 \subset S$ be a closed subscheme with the same underlying
topological space (for example if the ideal sheaf of $S_0$ in $S$
has square zero). The functor
$$
X \longmapsto X_0 = S_0 \times_S X
$$
defines an equivalence of categories
$$
\{
\text{schemes }X\text{ \'etale over }S
\}
\leftrightarrow
\{
\text{schemes }X_0\text{ \'etale over }S_0
\}
$$

\label{lemma-composition-finite-type-blowups}
\begin{slogan}
Composition of blowing ups is a blowing up
\end{slogan}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $Z \subset X$ be a closed subscheme of finite presentation.
Let $b : X' \to X$ be the blowing up with center $Z$. Let $Z' \subset X'$ be
a closed subscheme of finite presentation.
Let $X'' \to X'$ be the blowing up with center $Z'$.
There exists a closed subscheme $Y \subset X$ of finite presentation,
such that
\begin{enumerate}
\item $Y = Z \cup b(Z')$ set theoretically, and
\item the composition $X'' \to X$ is isomorphic to the blowing up
of $X$ in $Y$.
\end{enumerate}

\label{lemma-face-degeneracy}
Any morphism in $\Delta$ can be written as a composition
of the morphisms $\delta^n_j$ and $\sigma^n_j$.

\label{lemma-effective-Cartier-divisor-Sk}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be an
effective Cartier divisor. If $X$ is $(S_k)$, then $D$ is $(S_{k - 1})$.

\label{lemma-cohomology-bounded-above}
Let $\mathcal{A}$ be an abelian category.
Let $K^\bullet$ be a complex of $\mathcal{A}$.
\begin{enumerate}
\item If $K^\bullet$ has a projective resolution then
$H^n(K^\bullet) = 0$ for $n \gg 0$.
\item If $H^n(K^\bullet) = 0$ for $n \gg 0$ then there
exists a quasi-isomorphism $L^\bullet \to K^\bullet$
with $L^\bullet$ bounded above.
\end{enumerate}

\label{lemma-check-reflexive}
Let $X$ be an integral locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module
for all $x \in X$,
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module
for all closed points $x \in X$.
\end{enumerate}

\label{lemma-limit-K-injectives}
\begin{slogan}
The limit of a ``split'' tower of K-injective complexes is K-injective.
\end{slogan}
Let $\mathcal{A}$ be an abelian category. Let
$$
\ldots \to I_3^\bullet \to I_2^\bullet \to I_1^\bullet
$$
be an inverse system of complexes. Assume
\begin{enumerate}
\item each $I_n^\bullet$ is $K$-injective,
\item each map $I_{n + 1}^m \to I_n^m$ is a split surjection,
\item the limits $I^m = \lim I_n^m$ exist.
\end{enumerate}
Then the complex $I^\bullet$ is K-injective.

\label{lemma-split}
Let $\mathcal{D}$ be a pre-triangulated category.
Let $(X, Y, Z, f, g, h)$ be a distinguished triangle.
\begin{enumerate}
\item If $h = 0$, then there exists a right inverse $s : Z \to Y$ to $g$.
\item For any right inverse $s : Z \to Y$ of $g$ the map
$f \oplus s : X \oplus Z \to Y$ is an isomorphism.
\item For any objects $X', Z'$ of $\mathcal{D}$ the triangle
$(X', X' \oplus Z', Z', (1, 0), (0, 1), 0)$ is distinguished.
\end{enumerate}

\label{lemma-reflexive-S2}
Let $R$ be a Noetherian domain. Let $M$ be a finite reflexive $R$-module.
Let $\mathfrak p \subset R$ be a prime ideal.
\begin{enumerate}
\item If $\text{depth}(R_\mathfrak p) \geq 2$, then
$\text{depth}(M_\mathfrak p) \geq 2$.
\item If $R$ is $(S_2)$, then $M$ is $(S_2)$.
\end{enumerate}

\label{lemma-geometrically-normal-stein}
Let $k$ be a field. Let $X$ be a proper geometrically normal scheme over $k$.
The following are equivalent
\begin{enumerate}
\item $H^0(X, \mathcal{O}_X) = k$,
\item $X$ is geometrically connected,
\item $X$ is geometrically irreducible, and
\item $X$ is geometrically integral.
\end{enumerate}

\label{lemma-C-is-faithful}
For a ring $R$, the functor $C : \text{Mod}_R \to \text{Mod}_R$ is
exact and reflects injections and surjections.

\label{lemma-absolutely-integrally-closed-henselian-pair}
Let $A$ be absolutely integrally closed. Let $I \subset A$ be an ideal.
Then $(A, I)$ is a henselian pair if (and only if) the following
conditions hold
\begin{enumerate}
\item $I$ is contained in the Jacobson radical of $A$,
\item $A \to A/I$ induces a bijection on idempotents.
\end{enumerate}

\label{lemma-cut-by-koszul-flat}
Let $A' \to B'$ be a ring map. Let $I \subset A'$ be an ideal.
Set $A = A'/I$ and $B = B'/IB'$. Let $f'_1, \ldots, f'_r \in B'$. Assume
\begin{enumerate}
\item $A' \to B'$ is flat and of finite presentation,
\item $I$ is locally nilpotent,
\item the images $f_1, \ldots, f_r \in B$ form a quasi-regular sequence,
\item $B/(f_1, \ldots, f_r)$ is flat over $A$.
\end{enumerate}
Then $B'/(f'_1, \ldots, f'_r)$ is flat over $A'$.

\label{lemma-dim-1-noetherian-integral-separated-has-ample}
Let $X$ be a Noetherian integral separated scheme of dimension $1$.
Then $X$ has an ample invertible sheaf.

\label{lemma-Nagata-local-smooth}
The property $\mathcal{P}(S) =$``$S$ is Nagata''
is local in the smooth topology.

\label{lemma-colimit-sheaves}
\begin{slogan}
Colimit in category of sheaves equals sheafification of colimit in
category of presheaves.
\end{slogan}
Let $\mathcal{F} : \mathcal{I} \to \Sh(\mathcal{C})$
be a diagram. Then $\colim_\mathcal{I} \mathcal{F}$ exists
and is the sheafification of the colimit in the category of presheaves.

\label{lemma-computes-shift}
Assumptions and notation as in
Situation \ref{situation-derived-functor}.
Let $X$ be an object of $\mathcal{D}$ and $n \in \mathbf{Z}$.
\begin{enumerate}
\item $X$ computes $RF$ if and only if $X[n]$ computes $RF$.
\item $X$ computes $LF$ if and only if $X[n]$ computes $LF$.
\end{enumerate}

\label{lemma-group-scheme-over-field-separated}
Let $G$ be a group scheme over a field.
Then $G$ is a separated scheme.

\label{lemma-tangent-space}
The set of dotted arrows making (\ref{equation-tangent-space}) commute
has a canonical $\kappa(x)$-vector space structure.

\label{lemma-regular-functions-proper-variety}
Let $X$ be a proper variety over $k$. Then
\begin{enumerate}
\item $K = H^0(X, \mathcal{O}_X)$ is a field which is
a finite extension of the field $k$,
\item if $X$ is geometrically reduced, then $K/k$ is separable,
\item if $X$ is geometrically irreducible, then $K/k$
is purely inseparable,
\item if $X$ is geometrically integral, then $K = k$.
\end{enumerate}

\label{lemma-regular-local-smooth}
The property $\mathcal{P}(S) =$``$S$ is regular''
is local in the smooth topology.

\label{lemma-descending-fppf-property-immersion}
The property $\mathcal{P}(f) =$``$f$ is an immersion''
is fppf local on the base.

\label{lemma-differential-objects-abelian}
\begin{slogan}
The category of differential objects of an abelian category is itself
an abelian category.
\end{slogan}
Let $\mathcal{A}$ be an abelian category.
The category of differential objects of $\mathcal{A}$ is abelian.

\label{lemma-products}
Let $\mathcal{A}$ be an abelian category with exact
countable products. Then
\begin{enumerate}
\item $D(\mathcal{A})$ has countable products,
\item countable products $\prod K_i$ in $D(\mathcal{A})$ are obtained by
taking termwise products of any complexes representing the $K_i$, and
\item $H^p(\prod K_i) = \prod H^p(K_i)$.
\end{enumerate}

\label{lemma-injective-flasque}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Then any injective $\mathcal{O}_X$-module is flasque.

\label{lemma-smooth-regular}
\begin{slogan}
Smooth over a field implies regular
\end{slogan}
Let $X \to \Spec(k)$ be a smooth morphism where $k$ is a field.
Then $X$ is a regular scheme.

\label{lemma-geometric-genus-normalization}
Let $k$ be a field. Let $X$ be a proper scheme of dimension $\leq 1$ over $k$.
Then
\begin{enumerate}
\item We have $g_{geom}(X/k) = g_{geom}(X_{red}/k)$.
\item If $X' \to X$ is a birational proper morphism, then
$g_{geom}(X'/k) = g_{geom}(X/k)$.
\item If $X^\nu \to X$ is the normalization morphism, then
$g_{geom}(X^\nu/k) = g_{geom}(X/k)$.
\end{enumerate}

\label{lemma-reflexive-over-normal}
Let $X$ be an integral locally Noetherian normal scheme.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item $\mathcal{F}$ is torsion free and has property $(S_2)$, and
\item there exists an open subscheme $j : U \to X$ such that
\begin{enumerate}
\item every irreducible component of $X \setminus U$
has codimension $\geq 2$ in $X$,
\item $j^*\mathcal{F}$ is finite locally free, and
\item $\mathcal{F} = j_*j^*\mathcal{F}$.
\end{enumerate}
\end{enumerate}

\label{lemma-geometrically-reduced-at-point}
\begin{slogan}
Geometric reducedness can be checked on local rings.
\end{slogan}
Let $k$ be a field.
Let $X$ be a scheme over $k$.
Let $x \in X$.
The following are equivalent
\begin{enumerate}
\item $X$ is geometrically reduced at $x$, and
\item the ring $\mathcal{O}_{X, x}$ is geometrically
reduced over $k$ (see
Algebra, Definition \ref{algebra-definition-geometrically-reduced}).
\end{enumerate}

\label{lemma-scheme-theoretically-dense-contain-embedded-points}
Let $X$ be a locally Noetherian scheme. Let $U \subset X$ be an
open subscheme. The following are equivalent
\begin{enumerate}
\item $U$ is scheme theoretically dense in $X$
(Morphisms, Definition \ref{morphisms-definition-scheme-theoretically-dense}),
\item $U$ is dense in $X$ and $U$ contains all embedded points of $X$, and
\item $U$ contains all associated points of $X$.
\end{enumerate}

\label{lemma-direct-sum-defined}
Assumptions and notation as in Situation \ref{situation-derived-functor}.
Let $X, Y$ be objects of $\mathcal{D}$.
\begin{enumerate}
\item If $RF$ is defined at $X$ and $Y$, then $RF$ is defined at $X \oplus Y$.
\item If $\mathcal{D}'$ is Karoubian and $RF$ is defined at $X \oplus Y$,
then $RF$ is defined at both $X$ and $Y$.
\end{enumerate}
In either case we have $RF(X \oplus Y) = RF(X) \oplus RF(Y)$.
Similarly for $LF$.

\label{lemma-surjective-flat-epi}
A surjective and flat morphism is an epimorphism in the
category of schemes.

\label{lemma-nodal-family-etale-local-source}
Let $f : X \to S$ be a morphism of schemes. Let $\{U_i \to X\}$
be an \'etale covering. The following are equivalent
\begin{enumerate}
\item $f$ is at-worst-nodal of relative dimension $1$,
\item each $U_i \to S$ is at-worst-nodal of relative dimension $1$.
\end{enumerate}
In other words, being at-worst-nodal of relative dimension $1$
is \'etale local on the source.

\label{lemma-compose-formally-smooth}
A composition of formally smooth continuous homomorphisms of linearly
topologized rings is formally smooth.

\label{lemma-diagonal}
Let $S$ be a scheme.
Let $(U, R, s, t, c)$ be a groupoid over $S$.
Let $G \to U$ be the stabilizer group scheme.
\begin{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_S U$ is separated,
\item $G \to U$ is separated, and
\item $e : U \to G$ is a closed immersion.
\end{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_S U$ is quasi-separated,
\item $G \to U$ is quasi-separated, and
\item $e : U \to G$ is quasi-compact.
\end{enumerate}
\end{enumerate}

\label{lemma-relative-frobenius-endomorphism-identity}
Let $p > 0$ be a prime number. Let $S$ be a scheme in characteristic $p$.
Let $f : X \to Y$ be a morphism of schemes over $S$ .
Then the diagram
$$
\xymatrix{
X \ar[d]_f \ar[r]_{F_{X/S}} & X^{(p)} \ar[d]^{f^{(p)}} \\
Y \ar[r]^{F_{Y/S}} & Y^{(p)}
}
$$
commutes.

\label{lemma-descending-property-open-immersion}
The property $\mathcal{P}(f) =$``$f$ is an open immersion''
is fpqc local on the base.

\label{lemma-strict-transform-flat}
In the situation of Definition \ref{definition-strict-transform}.
\begin{enumerate}
\item If $X$ is flat over $S$ at all points lying over $Z$, then
the strict transform of $X$ is equal to the base change $X \times_S S'$.
\item Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
If $\mathcal{F}$ is flat over $S$ at all points lying over $Z$, then
the strict transform $\mathcal{F}'$ of $\mathcal{F}$ is equal to the
pullback $\text{pr}_X^*\mathcal{F}$.
\end{enumerate}

\label{lemma-descent-fs}
Let $R$, $S$ be rings. Let $\mathfrak n \subset S$ be an ideal.
Let $R \to R'$ be a ring map. Set $S' = S \otimes_R R'$ and
$\mathfrak n' = \mathfrak nS$. If
\begin{enumerate}
\item the map $R \to R'$ embeds $R$ as a direct summand of $R'$
as an $R$-module, and
\item $R' \to S'$ is formally smooth for the $\mathfrak n'$-adic topology,
\end{enumerate}
then $R \to S$ is formally smooth in the $\mathfrak n$-adic topology.

\label{lemma-localize-cartesian-square}
Let $\mathcal{C}$ be a site. Let
$$
\xymatrix{
U' \ar[d] \ar[r] & U \ar[d] \\
V' \ar[r] & V
}
$$
be a commutative diagram of $\mathcal{C}$. The
morphisms of Lemma \ref{lemma-relocalize}
produce commutative diagrams
$$
\vcenter{
\xymatrix{
\mathcal{C}/U' \ar[d]_{j_{U'/V'}} \ar[r]_{j_{U'/U}} &
\mathcal{C}/U \ar[d]^{j_{U/V}} \\
\mathcal{C}/V' \ar[r]^{j_{V'/V}} & \mathcal{C}/V
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Sh(\mathcal{C}/U') \ar[d]_{j_{U'/V'}} \ar[r]_{j_{U'/U}} &
\Sh(\mathcal{C}/U) \ar[d]^{j_{U/V}} \\
\Sh(\mathcal{C}/V') \ar[r]^{j_{V'/V}} &
\Sh(\mathcal{C}/V)
}
}
$$
of continuous and cocontinuous functors and of topoi.
Moreover, if the initial diagram of $\mathcal{C}$ is cartesian,
then we have
$j_{V'/V}^{-1} \circ j_{U/V, *} = j_{U'/V', *} \circ j_{U'/U}^{-1}$.

\label{lemma-nodal-lci}
Let $k$ be a field. Let $X$ be a locally algebraic $k$-scheme
equidimensional of dimension $1$.
The following are equivalent
\begin{enumerate}
\item the singularities of $X$ are at-worst-nodal, and
\item $X$ is a local complete intersection over $k$
and the closed subscheme $Z \subset X$ cut out by the
first fitting ideal of $\Omega_{X/k}$ is unramified over $k$.
\end{enumerate}

\label{lemma-bounded-flat-K-flat}
Let $(X, \mathcal{O}_X)$ be a ringed space. A bounded above complex
of flat $\mathcal{O}_X$-modules is K-flat.

\label{lemma-descending-property-quasi-affine}
The property $\mathcal{P}(f) =$``$f$ is quasi-affine''
is fpqc local on the base.

\label{lemma-genus-plane-curve}
Let $Z \subset \mathbf{P}^2_k$ be as in Lemma \ref{lemma-equation-plane-curve}
and let $I(Z) = (F)$ for some $F \in k[T_0, T_1, T_2]$.
Then $H^0(Z, \mathcal{O}_Z) = k$ and the genus of $Z$ is
$(d - 1)(d - 2)/2$ where $d = \deg(F)$.

\label{lemma-norm-quasi-affine}
Let $\pi : X \to Y$ be a finite morphism of schemes. Assume $X$ is quasi-affine
and there exists a norm of degree $d$ for $\pi$. Then $Y$ is quasi-affine.

\label{theorem-sections-unramified-maps}
Let $Y$ be a connected scheme.
Let $f : X \to Y$ be unramified and separated.
Every section of $f$ is an isomorphism onto a connected component.
There exists a bijective correspondence
$$
\text{sections of }f
\leftrightarrow
\left\{
\begin{matrix}
\text{connected components }X'\text{ of }X\text{ such that}\\
\text{the induced map }X' \to Y\text{ is an isomorphism}
\end{matrix}
\right\}
$$
In particular, given $x \in X$ there is at most one
section passing through $x$.

\label{proposition-vanishing-Noetherian}
\begin{reference}
\cite[Theorem 3.6.5]{Tohoku}.
\end{reference}
Let $X$ be a Noetherian topological space.
If $\dim(X) \leq d$, then $H^p(X, \mathcal{F}) = 0$
for all $p > d$ and any abelian sheaf $\mathcal{F}$
on $X$.

\label{lemma-reduced-local-smooth}
The property $\mathcal{P}(S) =$``$S$ is reduced'' is local in the smooth
topology.

\label{lemma-transitive-colimit-lci-at-end}
Let $A \to B \to C$ be ring maps.
If $B \to C$ is a filtered colimit of local complete intersection
homomorphisms then the conclusion of
Lemma \ref{lemma-transitive-lci-at-end}
remains valid.

\label{lemma-valuation-ring-torsion-free-flat}
Let $A$ be a valuation ring.
An $A$-module $M$ is flat over $A$ if and only if $M$ is torsion free.

\label{lemma-pushforward-restriction}
Let $(X, \mathcal{O}_X)$ be a ringed space. Let $j : U \to X$ be an
open subspace. Let $T \subset X$ be a closed subset contained in $U$.
\begin{enumerate}
\item If $E$ is an object of $D(\mathcal{O}_X)$ whose cohomology sheaves
are supported on $T$, then $E \to Rj_*(E|_U)$ is an isomorphism.
\item If $F$ is an object of $D(\mathcal{O}_U)$ whose cohomology sheaves
are supported on $T$, then $j_!F \to Rj_*F$ is an isomorphism.
\end{enumerate}

\label{lemma-descending-property-finite-presentation}
The property $\mathcal{P}(f) =$``$f$ is of finite presentation''
is fpqc local on the base.

\label{lemma-dimension-at-point-local}
Let $f : U \to V$ be an \'etale morphism of schemes.
Let $u \in U$ and $v = f(u)$. Then $\dim_u(U) = \dim_v(V)$.

\label{lemma-split-morphism-kernel-cokernel}
Let $\mathcal{A}$ be a preadditive category,
$x$ and $y$ be objects of $\mathcal{A}$,
and $j : y \to x$ and $q : x \to y$ be morphisms
satisfying $q \circ j = \text{id} _ y$.
Then
\begin{enumerate}
\item $\text{id} _ x - j \circ q$ has kernel $j$.
\item $\text{id} _ x - j \circ q$ has cokernel $q$.
\end{enumerate}

\label{lemma-reflexive-S2}
Let $X$ be an integral locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent reflexive $\mathcal{O}_X$-module.
Let $x \in X$.
\begin{enumerate}
\item If $\text{depth}(\mathcal{O}_{X, x}) \geq 2$, then
$\text{depth}(\mathcal{F}_x) \geq 2$.
\item If $X$ is $(S_2)$, then $\mathcal{F}$ is $(S_2)$.
\end{enumerate}

\label{lemma-glue-separated}
In Situation \ref{situation-glue} assume $A$ is a Noetherian
ring of dimension $1$. The following are equivalent
\begin{enumerate}
\item $A \otimes B \to K$ is not surjective,
\item there exists a discrete valuation ring $\mathcal{O} \subset K$
containing both $A$ and $B$.
\end{enumerate}

\label{lemma-descent-data-sheaves}
Let $\tau \in \{Zariski, fppf, \etale, smooth, syntomic\}$\footnote{The
fact that fpqc is missing is not a typo. See discussion
in Topologies, Section \ref{topologies-section-fpqc}.}.
Let $\Sch_\tau$ be a big $\tau$-site.
Let $S \in \Ob(\Sch_\tau)$.
Let $\{S_i \to S\}_{i \in I}$ be a covering in the
site $(\Sch/S)_\tau$. There is an equivalence of
categories
$$
\left\{
\begin{matrix}
\text{descent data }(X_i, \varphi_{ii'})\text{ such that}\\
\text{each }X_i \in \Ob((\Sch/S)_\tau)
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{sheaves }F\text{ on }(\Sch/S)_\tau\text{ such that}\\
\text{each }h_{S_i} \times F\text{ is representable}
\end{matrix}
\right\}.
$$
Moreover,
\begin{enumerate}
\item the objects representing $h_{S_i} \times F$ on the right hand side
correspond to the schemes $X_i$ on the left hand side, and
\item the sheaf $F$ is representable if and only if the
corresponding descent datum $(X_i, \varphi_{ii'})$ is effective.
\end{enumerate}

\label{lemma-family-is-one}
Let $S$ be a scheme.
Let $\{X_i \to S\}_{i \in I}$ be a family of morphisms with target $S$.
Set $X = \coprod_{i \in I} X_i$, and consider it as an $S$-scheme.
There is a canonical equivalence of categories
$$
\begin{matrix}
\text{category of descent data } \\
\text{relative to the family } \{X_i \to S\}_{i \in I}
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } X/S
\end{matrix}
$$
which maps $(V_i, \varphi_{ij})$ to $(V, \varphi)$ with
$V = \coprod_{i\in I} V_i$ and $\varphi = \coprod \varphi_{ij}$.

\label{lemma-descending-property-smooth}
The property $\mathcal{P}(f) =$``$f$ is smooth''
is fpqc local on the base.

\label{lemma-check-injective-on-ass}
Let $R$ be a Noetherian ring. Let $\varphi : M \to N$ be a map of
$R$-modules. Assume that for every prime $\mathfrak p$
of $R$ at least one of the following happens
\begin{enumerate}
\item $M_\mathfrak p \to N_\mathfrak p$ is injective, or
\item $\mathfrak p \not \in \text{Ass}(M)$.
\end{enumerate}
Then $\varphi$ is injective.

\label{proposition-properties-sections}
Sections of unramified morphisms.
\begin{enumerate}
\item Any section of an unramified morphism is an open immersion.
\item Any section of a separated morphism is a closed immersion.
\item Any section of an unramified separated morphism is open and closed.
\end{enumerate}

\label{lemma-abelian-variety-abelian}
An abelian variety is an abelian group scheme, i.e., the group
law is commutative.

\label{lemma-equalizer-CM}
For $(M, \theta) \in DD_{S/R}$, the diagram
\begin{equation}
\label{equation-coequalizer-CM}
\xymatrix@C=8pc{
C(M \otimes_{S, \delta_{12}^1} S_3)
\ar@<1ex>[r]^{C((\theta \otimes \delta_2^2) \circ (1_M \otimes \delta^2_0))}
\ar@<-1ex>[r]_{C(1_{M \otimes S_2} \otimes \delta^2_1)} &
C(M \otimes_{S, \delta_1^1} S_2 )
\ar[r]^{C(\theta \circ (1_M \otimes \delta_0^1))} & C(M).
}
\end{equation}
obtained by applying $C$ to (\ref{equation-equalizer-M}) is a split
coequalizer.

\label{lemma-colimit-coherent}
Let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
Assume that
\begin{enumerate}
\item $U$, $R$ are Noetherian,
\item $s, t$ are flat, quasi-compact, and quasi-separated.
\end{enumerate}
Then every quasi-coherent module $(\mathcal{F}, \beta)$ on $(U, R, s, t, c)$
is a filtered colimit of coherent modules.

\label{lemma-effective-Cartier-codimension-1}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item Let $D \subset X$ be a locally principal closed subscheme.
Let $\xi \in D$ be a generic point of an irreducible component of $D$.
Then $\dim(\mathcal{O}_{X, \xi}) \leq 1$.
\item Let $D \subset X$ be an effective Cartier divisor.
Let $\xi \in D$ be a generic point of an irreducible component of $D$.
Then $\dim(\mathcal{O}_{X, \xi}) = 1$.
\end{enumerate}

\label{lemma-content-finitely-generated}
Let $A$ be a ring. Let $M$ be a flat $A$-module. Let $x \in M$.
The content ideal of $x$, if it exists, is finitely generated.

\label{lemma-quasi-regular-immersion}
Let $i : Z \to X$ be an immersion of schemes. Then $i$ is a quasi-regular
immersion if and only if the following conditions are satisfied
\begin{enumerate}
\item $i$ is locally of finite presentation,
\item the conormal sheaf $\mathcal{C}_{Z/X}$ is finite locally free, and
\item the map (\ref{equation-conormal-algebra-quotient}) is an isomorphism.
\end{enumerate}

\label{lemma-pre-pre-delta-invariant}
Let $(A, \mathfrak m)$ be a Noetherian $1$-dimensional local ring.
Let $f \in \mathfrak m$. The following are equivalent
\begin{enumerate}
\item $\mathfrak m = \sqrt{(f)}$,
\item $f$ is not contained in any minimal prime of $A$, and
\item $A_f = \prod_{\mathfrak p\text{ minimal}} A_\mathfrak p$ as $A$-algebras.
\end{enumerate}
Such an $f \in \mathfrak m$ exists. If $\text{depth}(A) = 1$ (for example
$A$ is reduced), then (1) -- (3) are also equivalent to
\begin{enumerate}
\item[(4)] $f$ is a nonzerodivisor,
\item[(5)] $A_f$ is the total ring of fractions of $A$.
\end{enumerate}
If $A$ is reduced, then (1) -- (5) are also equivalent to
\begin{enumerate}
\item[(6)] $A_f$ is the product of the residue fields at the minimal
primes of $A$.
\end{enumerate}

\label{lemma-w-contractible}
Let $\mathcal{C}$ be a site. Let $U$ be an object of $\mathcal{C}$.
The following conditions are equivalent
\begin{enumerate}
\item For every covering $\{U_i \to U\}$ there exists a map of
sheaves $h_U^\# \to \coprod h_{U_i}^\#$ right inverse to the sheafification
of $\coprod h_{U_i} \to h_U$.
\item For every surjection of sheaves of sets $\mathcal{F} \to \mathcal{G}$
the map $\mathcal{F}(U) \to \mathcal{G}(U)$ is surjective.
\end{enumerate}

\label{proposition-descent-module}
\begin{slogan}
Effective descent for modules along faithfully flat ring maps.
\end{slogan}
Let $R \to A$ be a faithfully flat ring map.
Then
\begin{enumerate}
\item any descent datum on modules with respect to $R \to A$
is effective,
\item the functor $M \mapsto (A \otimes_R M, can)$ from $R$-modules
to the category of descent data is an equivalence, and
\item the inverse functor is given by $(N, \varphi) \mapsto H^0(s(N_\bullet))$.
\end{enumerate}

\label{lemma-henselization-change-ideal}
\begin{slogan}
The henselization of a pair only depends on the radical of the ideal
\end{slogan}
Let $A$ be a ring with ideals $I$ and $J$. If $V(I) = V(J)$ then the functor
of Lemma \ref{lemma-henselization} produces the same ring for the pair
$(A, I)$ as for the pair $(A, J)$.

\label{lemma-five-lemma}
\begin{reference}
\cite[Lemma 4.5 page 16]{Eilenberg-Steenrod}
\end{reference}
Let $\mathcal{A}$ be an abelian category. Let
$$
\xymatrix{
v \ar[r] \ar[d]^\alpha &
w \ar[r] \ar[d]^\beta &
x \ar[r] \ar[d]^\gamma &
y \ar[r] \ar[d]^\delta &
z \ar[d]^\epsilon \\
v' \ar[r] & w' \ar[r] & x' \ar[r] & y' \ar[r] & z'
}
$$
be a commutative diagram with exact rows. If $\beta, \delta$
are isomorphisms, $\epsilon$ is injective, and $\alpha$ is surjective
then $\gamma$ is an isomorphism.

\label{lemma-smooth-relative-dimension-1}
A smooth morphism of relative dimension $1$ is
at-worst-nodal of relative dimension $1$.

\label{lemma-weakass-reduced}
Let $X$ be a reduced scheme. Then the weakly associated points of $X$
are exactly the generic points of the irreducible components of $X$.

\label{lemma-projective-space-smooth}
\begin{slogan}
Projective space is smooth.
\end{slogan}
Let $k$ be a field and $n \geq 0$. Then $\mathbf{P}^n_k$ is a
smooth projective variety of dimension $n$ over $k$.

\label{lemma-characterize-trivial-pseudo-torsors}
In the situation of
Definition \ref{definition-pseudo-torsor}.
\begin{enumerate}
\item The scheme $X$ is a pseudo $G$-torsor if and only if for every scheme
$T$ over $S$ the set $X(T)$ is either empty or the action of the group $G(T)$
on $X(T)$ is simply transitive.
\item A pseudo $G$-torsor $X$ is trivial if and only if the morphism
$X \to S$ has a section.
\end{enumerate}

\label{lemma-reflexive-over-normal}
Let $R$ be a Noetherian normal domain with fraction field $K$.
Let $M$ be a finite $R$-module. The following are equivalent
\begin{enumerate}
\item $M$ is reflexive,
\item $M$ is torsion free and has property $(S_2)$,
\item $M$ is torsion free and
$M = \bigcap_{\text{height}(\mathfrak p) = 1} M_{\mathfrak p}$
where the intersection happens in $M_K = M \otimes_R K$.
\end{enumerate}

\label{lemma-is-limit-spaltenstein}
\begin{reference}
\cite[Proposition 3.13]{Spaltenstein}
\end{reference}
Let $(X, \mathcal{O}_X)$ be a ringed space. Let $E \in D(\mathcal{O}_X)$.
Assume that for every $x \in X$ there exist an integer $d_x \geq 0$ and
a fundamental system $\mathfrak{U}_x$ of open neighbourhoods of $x$
such that
$$
H^p(U, H^q(E)) = 0 \text{ for }
U \in \mathfrak{U}_x,\ p > d_x, \text{ and }q < 0
$$
Then the map $E \to R\lim \tau_{\geq -n} E$ of
Derived Categories, Remark
\ref{derived-remark-map-into-derived-limit-truncations}
is an isomorphism in $D(\mathcal{O}_X)$.

\label{lemma-vanishing-generated-one-section}
\begin{reference}
This is a special case of \cite[Proposition 3.6.1]{Tohoku}.
\end{reference}
Let $X$ be a topological space. Let $d \geq 0$ be an integer. Assume
\begin{enumerate}
\item $X$ is quasi-compact,
\item the quasi-compact opens form a basis for $X$, and
\item the intersection of two quasi-compact opens is quasi-compact.
\item $H^p(X, j_!\underline{\mathbf{Z}}_U) = 0$ for all $p > d$
and any quasi-compact open $j : U \to X$.
\end{enumerate}
Then $H^p(X, \mathcal{F}) = 0$ for all $p > d$
and any abelian sheaf $\mathcal{F}$ on $X$.

\label{lemma-node-over-separable-extension}
Let $k'/k$ be a finite separable field extension.
Let $X$ be a locally algebraic $k'$-scheme of dimension $1$.
Let $x \in X$ be a closed point. The following are equivalent
\begin{enumerate}
\item $x$ is a node, and
\item $x$ is a node when $X$ viewed as a locally algebraic $k$-scheme.
\end{enumerate}

\label{lemma-descending-property-quasi-compact}
The property $\mathcal{P}(f) =$``$f$ is quasi-compact''
is fpqc local on the base.

\label{lemma-smooth-pullback-normal-crossings}
\begin{slogan}
Pullback of a normal crossings divisor by a smooth
morphism is a normal crossings divisor.
\end{slogan}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be a
normal crossings divisor. If $f : Y \to X$ is a smooth
morphism of schemes, then the pullback $f^*D$ is a
normal crossings divisor on $Y$.

\label{lemma-henselization}
The inclusion functor
$$
\text{category of henselian pairs}
\longrightarrow
\text{category of pairs}
$$
has a left adjoint $(A, I) \mapsto (A^h, I^h)$.

\label{lemma-finite}
Let $k$ be a field. Let $f : X \to Y$ be a morphism of
schemes over $k$. Assume
\begin{enumerate}
\item $Y$ is separated over $k$,
\item $X$ is proper of dimension $\leq 1$ over $k$,
\item $f(Z)$ has at least two points for every irreducible
component $Z \subset X$ of dimension $1$.
\end{enumerate}
Then $f$ is finite.

\label{lemma-imshriek-sets}
If $U$ is an $m$-truncated simplicial set and $n > m$
then all $n$-simplices of $i_{m!}U$ are degenerate.

\label{lemma-universally-open-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is universally open''
is fppf local on the source.

\label{lemma-characterize-normal-crossings}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be a closed
subscheme. If $X$ is J-2 or Nagata, then the following are equivalent
\begin{enumerate}
\item $D$ is a normal crossings divisor in $X$,
\item for every $p \in D$ the pullback of $D$ to the spectrum of the
strict henselization $\mathcal{O}_{X, p}^{sh}$
is a strict normal crossings divisor.
\end{enumerate}

\label{lemma-consequence-baire-complete-module}
With same assumptions as Lemma \ref{lemma-baire-category-complete-module}
if $M = \bigcup_{n \geq 1} N_n$ for some closed subgroups $N_n$,
then $N_n$ is open for some $n$.

\label{lemma-syntomic-permanence}
Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& S
}
$$
be a commutative diagram of morphisms of schemes. Assume that
\begin{enumerate}
\item $f$ is surjective, flat, and locally of finite presentation,
\item $p$ is syntomic.
\end{enumerate}
Then both $q$ and $f$ are syntomic.

\label{lemma-fibre-product-integral}
In Situation \ref{situation-module-over-fibre-product}
if $B \to A$ is integral, then $B' \to A'$ is integral.

\label{lemma-map-from-cone}
Suppose that $f: K^\bullet \to L^\bullet$ and $g : L^\bullet \to M^\bullet$
are morphisms of complexes such that $g \circ f$ is homotopic to zero.
Then
\begin{enumerate}
\item $g$ factors through a morphism $C(f)^\bullet \to M^\bullet$, and
\item $f$ factors through a morphism $K^\bullet \to C(g)^\bullet[-1]$.
\end{enumerate}

\label{lemma-derived-shift}
\begin{slogan}
Derived functors are compatible with shifts
\end{slogan}
Assumptions and notation as in
Situation \ref{situation-derived-functor}.
Let $X$ be an object of $\mathcal{D}$ and $n \in \mathbf{Z}$.
\begin{enumerate}
\item $RF$ is defined at $X$ if and only if it is defined at $X[n]$.
In this case there is a canonical isomorphism
$RF(X)[n]= RF(X[n])$ between values.
\item $LF$ is defined at $X$ if and only if it is defined at $X[n]$.
In this case there is a canonical isomorphism
$LF(X)[n] \to LF(X[n])$ between values.
\end{enumerate}

\label{lemma-descending-property-locally-finite-presentation}
The property $\mathcal{P}(f) =$``$f$ is locally of finite presentation''
is fpqc local on the base.

\label{lemma-descending-property-proper}
The property $\mathcal{P}(f) =$``$f$ is proper''
is fpqc local on the base.

\label{lemma-brown}
\begin{reference}
\cite[Theorem 3.1]{Neeman-Grothendieck}.
\end{reference}
Let $\mathcal{D}$ be a triangulated category with direct sums which is
compactly generated. Let $H : \mathcal{D} \to \textit{Ab}$ be a contravariant
cohomological functor which transforms direct sums into products.
Then $H$ is representable.

\label{lemma-cokernel-map-double-dual-dvr}
Let $R$ be a discrete valuation ring and let $M$ be a finite $R$-module.
Then the map $j : M \to \Hom_R(\Hom_R(M, R), R)$ is surjective.

\label{lemma-change-rings-pic}
Let $A \to B$ be a faithfully flat ring map.
Let $X$ be a scheme over $A$ such that
\begin{enumerate}
\item $X$ is quasi-compact and quasi-separated, and
\item $R = H^0(X, \mathcal{O}_X)$ is a semi-local ring.
\end{enumerate}
Then the pullback map $\Pic(X) \to \Pic(X_B)$ is injective.

\label{lemma-descending-fppf-property-dominant}
The property $\mathcal{P}(f) =$``$f$ is dominant''
is fppf local on the base.

\label{lemma-node-field-extension}
Let $K/k$ be an extension of fields. Let $X$ be a locally algebraic
$k$-scheme of dimension $1$. Let $y \in X_K$ be a point with image
$x \in X$. The following are equivalent
\begin{enumerate}
\item $x$ is a closed point of $X$ and a node, and
\item $y$ is a closed point of $Y$ and a node.
\end{enumerate}

\label{lemma-finite-module-rank}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a finite type
quasi-coherent $\mathcal{O}_X$-module. Then
\begin{enumerate}
\item $\mathcal{F}$ has finite rank $r \geq 0$, and
\item there exists a nonempty open $U \subset X$
such that $\mathcal{F}|_U$ is free of rank $r$.
\end{enumerate}

\label{lemma-abelian-variety-projective}
Let $k$ be a field. Let $A$ be an abelian variety over $k$.
Then $A$ is projective.

\label{lemma-Jacobson-local-fppf}
The property $\mathcal{P}(S) =$``$S$ is Jacobson'' is local
in the fppf topology.

\label{lemma-descending-property-surjective}
The property $\mathcal{P}(f) =$``$f$ is surjective''
is fpqc local on the base.

\label{lemma-complete-henselian}
Let $(A, I)$ be a pair. If $A$ is $I$-adically complete, then
the pair is henselian.

\label{lemma-glue-valuation-ring}
In Situation \ref{situation-glue} assume that $B$ is a valuation ring.
Then for every unit $u$ of $A$ either $u \in R$ or $u^{-1} \in R$.

\label{lemma-dual-reflexive}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
Let $N$ be a finite reflexive $R$-module. Then $\Hom_R(M, N)$ is reflexive.

\label{lemma-flat}
Let $k$ be a field. Let $f : X \to Y$ be a nonconstant morphism
of curves over $k$. If $Y$ is normal, then $f$ is flat.

\label{lemma-cohomology-of-open}
Let $X$ be a ringed space.
Let $U \subset X$ be an open subspace.
\begin{enumerate}
\item If $\mathcal{I}$ is an injective $\mathcal{O}_X$-module
then $\mathcal{I}|_U$ is an injective $\mathcal{O}_U$-module.
\item For any sheaf of $\mathcal{O}_X$-modules $\mathcal{F}$ we have
$H^p(U, \mathcal{F}) = H^p(U, \mathcal{F}|_U)$.
\end{enumerate}

\label{lemma-tensor}
The total complex associated to the tensor product of two
strictly perfect complexes is strictly perfect.

\label{lemma-Rk-local-smooth}
The property $\mathcal{P}(S) =$``$S$ is locally Noetherian and $(R_k)$''
is local in the smooth topology.

\label{proposition-etale-CM}
\begin{slogan}
Being Cohen-Macaulay ascends and descends along \'etale maps.
\end{slogan}
Let $A$, $B$ be Noetherian local rings.
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then $A$ is Cohen-Macaulay if and only if $B$ is so.

\label{theorem-proper-base-change}
\begin{reference}
\cite[Expose V bis, 4.1.1]{SGA4}
\end{reference}
Consider a cartesian square of topological spaces
$$
\xymatrix{
X' = Y' \times_Y X \ar[d]_{f'} \ar[r]_-{g'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
Assume that $f$ is proper.
Let $E$ be an object of $D^+(X)$. Then the base change map
$$
g^{-1}Rf_*E \longrightarrow Rf'_*(g')^{-1}E
$$
of Lemma \ref{lemma-base-change-map-flat-case} is an isomorphism
in $D^+(Y')$.

\label{lemma-flat-torsion-free}
Let $X$ be an integral scheme. Any flat quasi-coherent $\mathcal{O}_X$-module
is torsion free.

\label{lemma-vanishing-for-profinite}
Let $X$ be a profinite topological space. Then $H^q(X, \mathcal{F}) = 0$
for all $q > 0$ and all abelian sheaves $\mathcal{F}$.

\label{lemma-hom-into-depth}
Let $R$ be a Noetherian local ring. Let $M$, $N$ be finite $R$-modules.
\begin{enumerate}
\item If $N$ has depth $\geq 1$, then $\Hom_R(M, N)$ has depth $\geq 1$.
\item If $N$ has depth $\geq 2$, then $\Hom_R(M, N)$ has depth $\geq 2$.
\end{enumerate}

\label{lemma-completion-CM}
Let $A$ be a Noetherian local ring.
Then $A$ is Cohen-Macaulay if and only if $A^\wedge$ is so.

\label{theorem-topology-and-topos}
Let $\mathcal{C}$ be a category.
Let $J$, $J'$ be topologies on $\mathcal{C}$.
The following are equivalent
\begin{enumerate}
\item $J = J'$,
\item sheaves for the topology $J$ are the same as
sheaves for the topology $J'$.
\end{enumerate}

\label{lemma-reflexive-depth-2}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is reflexive,
\item for every prime $\mathfrak p$ of $R$ one of the following happens
\begin{enumerate}
\item $M_\mathfrak p$ is a reflexive $R_\mathfrak p$-module, or
\item $\text{depth}(M_\mathfrak p) \geq 2$.
\end{enumerate}
\end{enumerate}

\label{lemma-descending-property-universal-homeomorphism}
The property $\mathcal{P}(f) =$``$f$ is a universal homeomorphism''
is fpqc local on the base.

\label{lemma-equalizer-M}
For $(M,\theta) \in DD_{S/R}$, the diagram
\begin{equation}
\label{equation-equalizer-M}
\xymatrix@C=8pc{
M \ar[r]^{\theta \circ (1_M \otimes \delta_0^1)} &
M \otimes_{S, \delta_1^1} S_2
\ar@<1ex>[r]^{(\theta \otimes \delta_2^2) \circ (1_M \otimes \delta^2_0)}
\ar@<-1ex>[r]_{1_{M \otimes S_2} \otimes \delta^2_1} & 
M \otimes_{S, \delta_{12}^1} S_3
}
\end{equation}
is a split equalizer.

\label{lemma-right-orthogonal}
Let $\mathcal{D}$ be a triangulated category. Let $E, K$ be objects
of $\mathcal{D}$. The following are equivalent
\begin{enumerate}
\item $\Hom(E, K[i]) = 0$ for all $i \in \mathbf{Z}$,
\item $\Hom(E', K) = 0$ for all $E' \in \langle E \rangle$.
\end{enumerate}

\label{lemma-criterion-very-ample-bis}
Let $k$ be a field. Let $X$ be a proper scheme over $k$ having dimension $1$
and $H^0(X, \mathcal{O}_X) = k$. Let $\mathcal{L}$ be an invertible
$\mathcal{O}_X$-module. Assume
\begin{enumerate}
\item $\mathcal{L}$ is globally generated,
\item $H^1(X, \mathcal{L}) = 0$, and
\item $\mathcal{L}$ is ample.
\end{enumerate}
Then $\mathcal{L}^{\otimes 2}$ is very ample on $X$ over $k$.

\label{lemma-descending-property-separated}
The property $\mathcal{P}(f) =$``$f$ is separated''
is fpqc local on the base.

\label{lemma-regular-point-on-curve}
Let $k$ be a field. Let $X$ be a curve over $k$. Let $x \in X$ be a closed
point. We think of $x$ as a (reduced) closed subscheme of $X$ with sheaf
of ideals $\mathcal{I}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{O}_{X, x}$ is regular,
\item $\mathcal{O}_{X, x}$ is normal,
\item $\mathcal{O}_{X, x}$ is a discrete valuation ring,
\item $\mathcal{I}$ is an invertible $\mathcal{O}_X$-module,
\item $x$ is an effective Cartier divisor on $X$.
\end{enumerate}
If $k$ is perfect or if $\kappa(x)$ is separable over $k$,
these are also equivalent to
\begin{enumerate}
\item[(6)] $X \to \Spec(k)$ is smooth at $x$.
\end{enumerate}

\label{lemma-bounded-below-injectives-K-injective}
Let $\mathcal{A}$ be an abelian category. A bounded below complex of
injectives is K-injective.

\label{lemma-apply-Leray}
Let $f : X \to Y$ be a morphism of ringed spaces.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module.
\begin{enumerate}
\item If $R^qf_*\mathcal{F} = 0$ for $q > 0$, then
$H^p(X, \mathcal{F}) = H^p(Y, f_*\mathcal{F})$ for all $p$.
\item If $H^p(Y, R^qf_*\mathcal{F}) = 0$ for all $q$ and $p > 0$, then
$H^q(X, \mathcal{F}) = H^0(Y, R^qf_*\mathcal{F})$ for all $q$.
\end{enumerate}

\label{lemma-flat-surjective-quasi-compact-monomorphism-isomorphism}
Let $f : X \to Y$ be a flat, quasi-compact, surjective monomorphism.
Then f is an isomorphism.

\label{lemma-direct-sum-from-product-essentially-constant}
Let $\mathcal{I}$ be a filtered category. Let $\mathcal{A}$
be an additive, Karoubian category. Let $F : \mathcal{I} \to \mathcal{A}$ and
$G : \mathcal{I} \to \mathcal{A}$ be functors. The following are equivalent
\begin{enumerate}
\item $F \oplus G : \mathcal{I} \to \mathcal{A}$
is essentially constant, and
\item $F$ and $G$ are essentially constant.
\end{enumerate}

\label{lemma-descending-property-universally-submersive}
The property $\mathcal{P}(f) =$``$f$ is universally submersive''
is fpqc local on the base.

\label{lemma-descending-property-relative-dimension-d}
The property $\mathcal{P}(f) =$``$f$ is locally of finite type
of relative dimension $d$'' is fpqc local on the base.

\label{lemma-third-object-zero}
Let $\mathcal{D}$ be a pre-triangulated category.
Let $f : X \to Y$ be a morphism of $\mathcal{D}$.
The following are equivalent
\begin{enumerate}
\item $f$ is an isomorphism,
\item $(X, Y, 0, f, 0, 0)$ is a distinguished triangle, and
\item for any distinguished triangle $(X, Y, Z, f, g, h)$ we have $Z = 0$.
\end{enumerate}

\label{lemma-geometrically-reduced-p}
Let $k$ be a field of characteristic $p > 0$. Let $X$ be a scheme over $k$.
Then $X$ is geometrically reduced if and only if $X^{(p)}$ is reduced.

\label{proposition-cohomological-dimension-spectral}
\begin{reference}
Part (1) is the main theorem of \cite{Scheiderer}.
\end{reference}
Let $X$ be a spectral space of Krull dimension $d$.
Let $\mathcal{F}$ be an abelian sheaf on $X$.
\begin{enumerate}
\item $H^q(X, \mathcal{F}) = 0$ for $q > d$,
\item $H^d(X, \mathcal{F}) \to H^d(U, \mathcal{F})$ is surjective
for every quasi-compact open $U \subset X$,
\item $H^q_Z(X, \mathcal{F}) = 0$ for $q > d$ and any constructible
closed subset $Z \subset X$.
\end{enumerate}

\label{lemma-hom-into-torsion-free}
Let $R$ be a domain. Let $M$, $N$ be $R$-modules.
If $N$ is torsion free, so is $\Hom_R(M, N)$.

\label{lemma-connected-group-scheme-over-field-irreducible}
Let $G$ be a group scheme over a field $k$. If $G$ is connected,
then $G$ is irreducible.

\label{proposition-connected-component}
Let $G$ be a group scheme over a field $k$. There exists a canonical closed
subgroup scheme $G^0 \subset G$ with the following properties
\begin{enumerate}
\item $G^0 \to G$ is a flat closed immersion,
\item $G^0 \subset G$ is the connected component of the identity,
\item $G^0$ is geometrically irreducible, and
\item $G^0$ is quasi-compact.
\end{enumerate}

\label{lemma-ampleness-in-terms-of-degrees-components}
Let $k$ be a field. Let $X$ be a proper scheme of dimension $\leq 1$
over $k$. Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Let $C_i \subset X$, $i = 1, \ldots, t$ be the irreducible components
of dimension $1$. The following are equivalent:
\begin{enumerate}
\item $\mathcal{L}$ is ample, and
\item $\deg(\mathcal{L}|_{C_i}) > 0$ for $i = 1, \ldots, t$.
\end{enumerate}

\label{lemma-composition-regular-immersion}
Let $i : Z \to Y$ and $j : Y \to X$ be immersions of schemes.
\begin{enumerate}
\item If $i$ and $j$ are regular immersions, so is $j \circ i$.
\item If $i$ and $j$ are Koszul-regular immersions, so is $j \circ i$.
\item If $i$ and $j$ are $H_1$-regular immersions, so is $j \circ i$.
\item If $i$ is an $H_1$-regular immersion and $j$ is a quasi-regular
immersion, then $j \circ i$ is a quasi-regular immersion.
\end{enumerate}

\label{lemma-geometrically-irreducible-function-field}
Let $X$ be an irreducible scheme over the field $k$. Let $\xi \in X$
be its generic point. The following are equivalent:
\begin{enumerate}
\item $X$ is geometrically irreducible over $k$;
\item $\kappa(\xi)$ is geometrically irreducible over $k$;
\item the separable algebraic closure of $k$ in $\kappa(\xi)$ is equal to $k$.
\end{enumerate}

\label{lemma-group-scheme-field-geometrically-irreducible}
Let $G$ be a group scheme over a field $k$.
Then
\begin{enumerate}
\item every local ring $\mathcal{O}_{G, g}$ of $G$ has a unique
minimal prime ideal,
\item there is exactly one irreducible component $Z$ of $G$
passing through $e$, and
\item $Z$ is geometrically irreducible over $k$.
\end{enumerate}

\label{lemma-normal-goes-up}
Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is regular,
\item $S$ is Noetherian, and
\item $R$ is Noetherian and normal.
\end{enumerate}
Then $S$ is normal.

\label{lemma-locally-finite-presentation-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite presentation''
is fppf local on the source.

\label{lemma-separate-disjoint-opens-by-blowing-up}
\begin{slogan}
Separate irreducible components by blowing up.
\end{slogan}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $U, V$ be quasi-compact disjoint open subschemes of $X$.
Then there exist a $U \cup V$-admissible blowup $b : X' \to X$
such that $X'$ is a disjoint union of open subschemes
$X' = X'_1 \amalg X'_2$ with $b^{-1}(U) \subset X'_1$ and
$b^{-1}(V) \subset X'_2$.

\label{lemma-perfect}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $E$ be an object of $D(\mathcal{O}_X)$.
The following are equivalent
\begin{enumerate}
\item $E$ is perfect, and
\item $E$ is pseudo-coherent and locally has finite tor dimension.
\end{enumerate}

\label{lemma-galois-action-connected-components-continuous}
Let $k$ be a field, with separable algebraic closure $\overline{k}$.
Let $X$ be a scheme over $k$.
Assume
\begin{enumerate}
\item $X$ is quasi-compact, and
\item the connected components of $X_{\overline{k}}$ are open.
\end{enumerate}
Then
\begin{enumerate}
\item[(a)] $\pi_0(X_{\overline{k}})$ is finite, and
\item[(b)] the action of $\text{Gal}(\overline{k}/k)$ on
$\pi_0(X_{\overline{k}})$ is continuous.
\end{enumerate}
Moreover, assumptions (1) and (2) are satisfied when $X$ is
of finite type over $k$.

\label{lemma-degree-more-than-2g-2}
\begin{reference}
\cite[Lemma 2]{Jongmin}
\end{reference}
In Situation \ref{situation-Cohen-Macaulay-curve}
assume $X$ is integral and has genus $g$.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Let $Z \subset X$ be a $0$-dimensional closed subscheme with ideal
sheaf $\mathcal{I} \subset \mathcal{O}_X$.
If $\deg(\mathcal{L}) > 2g - 2 + \deg(Z)$, then
$H^1(X, \mathcal{I}\mathcal{L}) = 0$ and one of the following possibilities
occurs
\begin{enumerate}
\item $H^0(X, \mathcal{I}\mathcal{L}) \not = 0$, or
\item $g = 0$ and $\deg(\mathcal{L}) = \deg(Z) - 1$.
\end{enumerate}
In case (2) if $Z = \emptyset$, then $X \cong \mathbf{P}^1_k$ and $\mathcal{L}$
corresponds to $\mathcal{O}_{\mathbf{P}^1}(-1)$.

\label{lemma-fibre-product-finite-type}
Let $R$ be a ring. Let $A \to B$ and $C \to B$ be $R$-algebra maps.
Assume
\begin{enumerate}
\item $R$ is Noetherian,
\item $A$, $B$, $C$ are of finite type over $R$,
\item $A \to B$ is surjective, and
\item $B$ is finite over $C$.
\end{enumerate}
Then $A \times_B C$ is of finite type over $R$.

\label{lemma-tor-amplitude}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $E$ be an object of $D(\mathcal{O}_X)$.
Let $a, b \in \mathbf{Z}$ with $a \leq b$. The following are equivalent
\begin{enumerate}
\item $E$ has tor-amplitude in $[a, b]$.
\item $E$ is represented by a complex
$\mathcal{E}^\bullet$ of flat $\mathcal{O}_X$-modules with
$\mathcal{E}^i = 0$ for $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-descent-lemma}
If $f$ is universally injective, then the diagram
\begin{equation}
\label{equation-equalizer-f2}
\xymatrix@C=8pc{
f_*(M, \theta) \otimes_R S
\ar[r]^{\theta \circ (1_M \otimes \delta_0^1)} &
M \otimes_{S, \delta_1^1} S_2 
\ar@<1ex>[r]^{(\theta \otimes \delta_2^2) \circ (1_M \otimes \delta^2_0)}
\ar@<-1ex>[r]_{1_{M \otimes S_2} \otimes \delta^2_1} &
M \otimes_{S, \delta_{12}^1} S_3
}
\end{equation}
obtained by tensoring (\ref{equation-equalizer-f}) over $R$ with $S$ is an 
equalizer.

\label{lemma-blowing-up-projective}
Let $X$ be a scheme. Let $\mathcal{I} \subset \mathcal{O}_X$ be a
quasi-coherent sheaf of ideals. Let $b : X' \to X$ be the blowing up of $X$
in the ideal sheaf $\mathcal{I}$. If $\mathcal{I}$ is of finite type, then
\begin{enumerate}
\item $b : X' \to X$ is a projective morphism, and
\item $\mathcal{O}_{X'}(1)$ is a $b$-relatively ample invertible sheaf.
\end{enumerate}

\label{proposition-criterion-points}
\begin{reference}
\cite[Expos\'e VI, Appendix by Deligne, Proposition 9.0]{SGA4}
\end{reference}
Let $\mathcal{C}$ be a site. Assume that
\begin{enumerate}
\item finite limits exist in $\mathcal{C}$, and
\item every covering $\{U_i \to U\}_{i \in I}$
has a refinement by a finite covering of $\mathcal{C}$.
\end{enumerate}
Then $\mathcal{C}$ has enough points.

\label{lemma-check-isomorphism-via-depth-and-ass}
Let $R$ be a Noetherian ring. Let $\varphi : M \to N$ be a map of
$R$-modules. Assume $M$ is finite and that for every prime $\mathfrak p$
of $R$ one of the following happens
\begin{enumerate}
\item $M_\mathfrak p \to N_\mathfrak p$ is an isomorphism, or
\item $\text{depth}(M_\mathfrak p) \geq 2$ and
$\mathfrak p \not \in \text{Ass}(N)$.
\end{enumerate}
Then $\varphi$ is an isomorphism.

\label{lemma-base-change-nodal-family}
Let $f : X \to S$ be at-worst-nodal of relative dimension $1$.
Then the same is true for any base change of $f$.

\label{lemma-essentially-constant-into-karoubian}
Let $\mathcal{I}$ be a category, let $\mathcal{A}$ be a pre-additive
Karoubian category, and let $M : \mathcal{I} \to \mathcal{A}$ be a diagram.
\begin{enumerate}
\item Assume $\mathcal{I}$ is filtered. The following are equivalent
\begin{enumerate}
\item $M$ is essentially constant,
\item $X = \colim M$ exists and there exists a cofinal filtered subcategory
$\mathcal{I}' \subset \mathcal{I}$ and for $i' \in \Ob(\mathcal{I}')$
a direct sum decomposition $M_{i'} = X_{i'} \oplus Z_{i'}$ such that
$X_{i'}$ maps isomorphically to $X$ and $Z_{i'}$ to zero in $M_{i''}$
for some $i' \to i''$ in $\mathcal{I}'$.
\end{enumerate}
\item Assume $\mathcal{I}$ is cofiltered. The following are equivalent
\begin{enumerate}
\item $M$ is essentially constant,
\item $X = \lim M$ exists and there exists an initial cofiltered subcategory
$\mathcal{I}' \subset \mathcal{I}$ and for $i' \in \Ob(\mathcal{I}')$
a direct sum decomposition $M_{i'} = X_{i'} \oplus Z_{i'}$
such that $X$ maps isomorphically to $X_{i'}$ and $M_{i''} \to Z_{i'}$
is zero for some $i'' \to i'$ in $\mathcal{I}'$.
\end{enumerate}
\end{enumerate}

\label{lemma-Karoubian-dual}
In a Karoubian additive monoidal category every summand
of an object which has a left dual has a left dual.

\label{lemma-Rhom-strictly-perfect-K-flat}
In the situation of Lemma \ref{lemma-Rhom-strictly-perfect}
if $\mathcal{F}^\bullet$ is K-flat, then $\mathcal{H}^\bullet$ is K-flat.

\label{theorem-descend-module-properties}
If $M \otimes_R S$ has one of the following properties as an $S$-module
\begin{enumerate}
\item[(a)]
finitely generated;
\item[(b)]
finitely presented;
\item[(c)]
flat;
\item[(d)]
faithfully flat;
\item[(e)]
finite projective;
\end{enumerate}
then so does $M$ as an $R$-module (and conversely).

\label{lemma-unbounded-right-derived}
Let $F : \mathcal{A} \to \mathcal{B}$ be a left exact functor of
abelian categories. Assume
\begin{enumerate}
\item every object of $\mathcal{A}$ is a subobject of an object
which is right acyclic for $F$,
\item there exists an integer $n \geq 0$ such that $R^nF = 0$,
\end{enumerate}
Then
\begin{enumerate}
\item $RF : D(\mathcal{A}) \to D(\mathcal{B})$ exists,
\item any complex consisting of right acyclic objects for $F$ computes $RF$,
\item any complex is the source of a quasi-isomorphism into a complex
consisting of right acyclic objects for $F$,
\item for $E \in D(\mathcal{A})$
\begin{enumerate}
\item $H^i(RF(\tau_{\leq a}E) \to H^i(RF(E))$ is an isomorphism
for $i \leq a$,
\item $H^i(RF(E)) \to H^i(RF(\tau_{\geq b - n + 1}E))$ is an isomorphism
for $i \geq b$,
\item if $H^i(E) = 0$ for $i \not \in [a, b]$ for some
$-\infty \leq a \leq b \leq \infty$, then $H^i(RF(E)) = 0$
for $i \not \in [a, b + n - 1]$.
\end{enumerate}
\end{enumerate}

\label{lemma-universal-effective-epimorphism-affine}
Let $\{f_i : X_i \to X\}_{i \in I}$ be a family of morphisms of affine schemes.
The following are equivalent
\begin{enumerate}
\item for any quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$ we have
$$
\Gamma(X, \mathcal{F}) =
\text{Equalizer}\left(
\xymatrix{
\prod\nolimits_{i \in I} \Gamma(X_i, f_i^*\mathcal{F})
\ar@<1ex>[r] \ar@<-1ex>[r] &
\prod\nolimits_{i, j \in I}
\Gamma(X_i \times_X X_j, (f_i \times f_j)^*\mathcal{F})
}
\right)
$$
\item $\{f_i : X_i \to X\}_{i \in I}$ is a universal effective epimorphism
(Sites, Definition \ref{sites-definition-universal-effective-epimorphisms})
in the category of affine schemes.
\end{enumerate}

\label{theorem-structure-etale}
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then there exist $f, g \in A[t]$ such that
\begin{enumerate}
\item $B' = A[t]_g/(f)$ is standard \'etale -- see (a) and (b) above, and
\item $B$ is isomorphic to a localization of $B'$ at a prime.
\end{enumerate}

\label{lemma-perfect-independent-representative}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $E$ be an object of $D(\mathcal{O}_X)$.
\begin{enumerate}
\item If there exists an open covering $X = \bigcup U_i$ and
strictly perfect complexes $\mathcal{E}_i^\bullet$ on $U_i$
such that $\mathcal{E}_i^\bullet$ represents $E|_{U_i}$ in
$D(\mathcal{O}_{U_i})$, then $E$ is perfect.
\item If $E$ is perfect, then any complex representing $E$ is perfect.
\end{enumerate}

\label{lemma-map-homology-homotopy}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If the maps $f, g : A_\bullet \to B_\bullet$ are
homotopic, then the induced maps $H_i(f)$ and $H_i(g)$
are equal.
\item If the map $f : A_\bullet \to B_\bullet$ is a homotopy
equivalence, then $f$ is a quasi-isomorphism.
\end{enumerate}

\label{lemma-reduced-quotient-regular-ring-dim-2}
Let $(A, \mathfrak m)$ be a regular local ring of dimension $2$.
Let $I \subset \mathfrak m$ be an ideal.
\begin{enumerate}
\item If $A/I$ is reduced, then $I = (0)$, $I = \mathfrak m$, or
$I = (f)$ for some nonzero $f \in \mathfrak m$.
\item If $A/I$ has depth $1$, then $I = (f)$ for some nonzero
$f \in \mathfrak m$. 
\end{enumerate}

\label{lemma-S1-no-embedded}
Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent sheaf on $X$.
Then the following are equivalent:
\begin{enumerate}
\item $\mathcal{F}$ has no embedded associated points, and
\item $\mathcal{F}$ has property $(S_1)$.
\end{enumerate}

\label{lemma-check-rank-on-affines}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. Let $r$ be a cardinal. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ has rank $r$,
\item for all $U \subset X$ nonempty affine open $\mathcal{F}(U)$
is an $\mathcal{O}_X(U)$-module of rank $r$, and
\item for some $U \subset X$ nonempty affine open $\mathcal{F}(U)$
is an $\mathcal{O}_X(U)$-module of rank $r$.
\end{enumerate}

\label{lemma-henselization-local-ring}
\begin{slogan}
Compatibility henselization of pairs and of local rings.
\end{slogan}
The functor of Lemma \ref{lemma-henselization} associates to a local ring
$(A, \mathfrak m)$ its henselization.

\label{lemma-trivial-kan-homotopy}
Let $f : X \to Y$ be a trivial Kan fibration of simplicial sets.
Then $f$ is a homotopy equivalence.

\label{lemma-codimension-1-is-effective-Cartier}
Let $Z \subset X$ be a closed subscheme of a Noetherian scheme. Assume
\begin{enumerate}
\item $Z$ has no embedded points,
\item every irreducible component of $Z$ has codimension $1$ in $X$,
\item every local ring $\mathcal{O}_{X, x}$, $x \in Z$ is
a UFD or $X$ is regular.
\end{enumerate}
Then $Z$ is an effective Cartier divisor.

\label{proposition-brown}
\begin{reference}
\cite[Theorem 4.1]{Neeman-Grothendieck}.
\end{reference}
Let $\mathcal{D}$ be a triangulated category with direct sums which is
compactly generated. Let $F : \mathcal{D} \to \mathcal{D}'$ be an
exact functor of triangulated categories which transforms direct sums
into direct sums. Then $F$ has an exact right adjoint.

\label{lemma-syntomic-syntomic-local-source}
The property $\mathcal{P}(f)=$``$f$ is syntomic''
is syntomic local on the source.

\label{lemma-henselization-integral}
\begin{slogan}
Henselization commutes with integral base change
\end{slogan}
Let $(A, I) \to (B, J)$ be a map of pairs such that $V(J) = V(IB)$.
Let $(A^h , I^h) \to (B^h, J^h)$ be the induced map
on henselizations (Lemma \ref{lemma-henselization}).
If $A \to B$ is integral, then the induced map
$A^h \otimes_A B \to B^h$ is an isomorphism.

\label{lemma-closed-subscheme-nodal-curve}
Let $k$ be a field. Let $X$ be a locally algebraic $k$-scheme
equidimensional of dimension $1$ whose singularities are at-worst-nodal.
If $Y \subset X$ is a reduced closed subscheme
equidimensional of dimension $1$, then
\begin{enumerate}
\item the singularities of $Y$ are at-worst-nodal, and
\item if $Z \subset X$ is the scheme theoretic closure of
$X \setminus Y$, then
\begin{enumerate}
\item the scheme theoretic intersection $Y \cap Z$ is
the disjoint union of spectra of finite separable extensions of $k$,
\item each point of $Y \cap Z$ is a node of $X$, and
\item $Y \to \Spec(k)$ is smooth at every point of $Y \cap Z$.
\end{enumerate}
\end{enumerate}

\label{lemma-map-cohomology-homotopy-cochain}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If the maps $f, g : A^\bullet \to B^\bullet$ are
homotopic, then the induced maps $H^i(f)$ and $H^i(g)$
are equal.
\item If $f : A^\bullet \to B^\bullet$ is a homotopy equivalence,
then $f$ is a quasi-isomorphism.
\end{enumerate}

\label{lemma-smooth-pullback-strict-normal-crossings}
\begin{slogan}
Pullback of a strict normal crossings divisor by a smooth
morphism is a strict normal crossings divisor.
\end{slogan}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be a
strict normal crossings divisor. If $f : Y \to X$ is a smooth
morphism of schemes, then the pullback $f^*D$ is a
strict normal crossings divisor on $Y$.

\label{lemma-semi-local}
In Situation \ref{situation-glue} assume
\begin{enumerate}
\item $A$ is a Noetherian semi-local domain of dimension $1$,
\item $B$ is a discrete valuation ring,
\end{enumerate}
Then we have the following two possibilities
\begin{enumerate}
\item[(a)] If $A^*$ is not contained in $R$, then
$\Spec(A) \to \Spec(R)$ and $\Spec(B) \to \Spec(R)$
are open immersions covering $\Spec(R)$ and $K = A \otimes_R B$.
\item[(b)] If $A^*$ is contained in $R$, then $B$ dominates one of
the local rings of $A$ at a maximal ideal and $A \otimes B \to K$
is not surjective.
\end{enumerate}

\label{lemma-node-etale-local}
Let $k$ be a field. Let $X$ be a locally algebraic
$k$-scheme of dimension $1$. Let $Y \to X$ be an \'etale morphism.
Let $y \in Y$ be a point with image $x \in X$. The following are equivalent
\begin{enumerate}
\item $x$ is a closed point of $X$ and a node, and
\item $y$ is a closed point of $Y$ and a node.
\end{enumerate}

\label{lemma-criterion-very-ample}
Let $k$ be a field. Let $X$ be a proper scheme over $k$ having dimension $1$
and $H^0(X, \mathcal{O}_X) = k$. Let $\mathcal{L}$ be an invertible
$\mathcal{O}_X$-module. Assume
\begin{enumerate}
\item $\mathcal{L}$ has a regular global section,
\item $H^1(X, \mathcal{L}) = 0$, and
\item $\mathcal{L}$ is ample.
\end{enumerate}
Then $\mathcal{L}^{\otimes 6}$ is very ample on $X$ over $k$.

\label{lemma-descend-reduced}
If $f : X \to Y$ is a flat and surjective morphism of schemes
and $X$ is reduced, then $Y$ is reduced.

\label{lemma-fully-faithful-cases}
Let $f : X \to S$ be a morphism of schemes. In the following
cases the functor (\ref{equation-descent-etale}) is fully faithful:
\begin{enumerate}
\item $f$ is surjective and universally closed
(e.g., finite, integral, or proper),
\item $f$ is surjective and universally open
(e.g., locally of finite presentation and flat, smooth, or etale),
\item $f$ is surjective, quasi-compact, and flat.
\end{enumerate}

\label{lemma-descend-along-finite-radicial}
Let $X \to Y$ be a surjective finite locally free morphism which is radicial. 
Let $V$ be a scheme over $X$. Then any descent datum on $V/X/Y$ is effective.

\label{lemma-reflexive-torsion-free}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module.
\begin{enumerate}
\item If $\mathcal{F}$ is reflexive, then $\mathcal{F}$ is torsion free.
\item The map $j : \mathcal{F} \longrightarrow \mathcal{F}^{**}$
is injective if and only if $\mathcal{F}$ is torsion free.
\end{enumerate}

\label{lemma-characterize-reflexive}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is reflexive,
\item there exists a short exact sequence $0 \to M \to F \to N \to 0$
with $F$ finite free and $N$ torsion free.
\end{enumerate}

\label{lemma-descending-property-closed-immersion}
The property $\mathcal{P}(f) =$``$f$ is a closed immersion''
is fpqc local on the base.

\label{lemma-check-exactness-fibre-product}
Let $\mathcal{A}$ be an abelian category. Let $f:x\to y$ and $g:y\to z$ 
be morphisms with $g\circ f=0$. Then, the following statements are equivalent:
\begin{enumerate}
\item The sequence $x\overset{f}\to y\overset{g}\to z$ is exact.
\item For every $h:w\to y$ with $g\circ h=0$ there exist an object $v$, 
an epimorphism $k:v\to w$ and a morphism $l:v\to x$ with $h\circ k=f\circ l$.
\end{enumerate}

\label{lemma-isom-depth-2-torsion-free}
Let $R$ be a Noetherian domain. Let $\varphi : M \to N$ be a map of
$R$-modules. Assume $M$ is finite, $N$ is torsion free, and
that for every prime $\mathfrak p$ of $R$ one of the following happens
\begin{enumerate}
\item $M_\mathfrak p \to N_\mathfrak p$ is an isomorphism, or
\item $\text{depth}(M_\mathfrak p) \geq 2$.
\end{enumerate}
Then $\varphi$ is an isomorphism.

\label{lemma-descending-property-dominant}
The property $\mathcal{P}(f) =$``$f$ is quasi-compact and dominant''
is fpqc local on the base.

\label{lemma-image-of-quasi-compact}
\begin{slogan}
Sheaf surjections transmit quasi-compactness.
\end{slogan}
Let $\mathcal{C}$ be a site.
\begin{enumerate}
\item If $U \to V$ is a morphism of $\mathcal{C}$ such that
$h_U^\# \to h_V^\#$ is surjective and $U$ is quasi-compact, then
$V$ is quasi-compact.
\item If $\mathcal{F} \to \mathcal{G}$ is a surjection of sheaves
of sets and $\mathcal{F}$ is quasi-compact, then $\mathcal{G}$
is quasi-compact.
\end{enumerate}

\label{lemma-valuation-ring-flat-essentially-finite-type}
Let $A$ be a valuation ring. Let $A \to B$ be a local homomorphism
which is essentially of finite type. Let $M$ be a finite $B$-module.
\begin{enumerate}
\item If $B$ is flat over $A$, then $B$ is essentially of finite
presentation over $A$.
\item If $M$ is flat as an $A$-module, then $M$ is finitely presented
as a $B$-module.
\end{enumerate}

\label{lemma-open-subscheme-UFD}
Let $R$ be a UFD. The Picard groups of the following are
trivial.
\begin{enumerate}
\item $\Spec(R)$ and any open subscheme of it.
\item $\mathbf{A}^n_R = \Spec(R[x_1, \ldots, x_n])$ and any open subscheme
of it.
\end{enumerate}
In particular, the Picard group of any open subscheme of affine
$n$-space $\mathbf{A}^n_k$ over a field $k$ is trivial.

\label{lemma-direct-sum-from-product-colimit}
Let $\mathcal{I}$ be a category. Let $\mathcal{A}$ be an additive, Karoubian
category. Let $F : \mathcal{I} \to \mathcal{A}$ and
$G : \mathcal{I} \to \mathcal{A}$ be functors. The following are equivalent
\begin{enumerate}
\item $\colim_\mathcal{I} F \oplus G$ exists, and
\item $\colim_\mathcal{I} F$ and $\colim_\mathcal{I} G$ exist.
\end{enumerate}
In this case $\colim_\mathcal{I} F \oplus G =
\colim_\mathcal{I} F \oplus \colim_\mathcal{I} G$.

\label{lemma-characterize-unramified-Noetherian}
\begin{slogan}
Unramifiedness is a stalk local condition.
\end{slogan}
Let $A \to B$ be of finite type with $A$ a Noetherian ring.
Let $\mathfrak q$ be a prime of $B$ lying over $\mathfrak p \subset A$.
Then $A \to B$ is unramified at $\mathfrak q$ if and only if
$A_{\mathfrak p} \to B_{\mathfrak q}$ is an unramified homomorphism
of local rings.

\label{lemma-reduced-subgroup-scheme-perfect}
Let $G$ be a group scheme over a perfect field $k$.
Then the reduction $G_{red}$ of $G$ is a closed subgroup scheme of $G$.

\label{lemma-open-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is open''
is fppf local on the source.

\label{lemma-etale-tau-local-source-target}
Let $\mathcal{P}$ be a property of morphisms of schemes. Assume
\begin{enumerate}
\item $\mathcal{P}$ is \'etale local on the source,
\item $\mathcal{P}$ is smooth local on the target,
\item $\mathcal{P}$ is stable under postcomposing with open immersions:
if $f : X \to Y$ has $\mathcal{P}$ and $Y \subset Z$ is an open
subscheme then $X \to Z$ has $\mathcal{P}$.
\end{enumerate}
Given a commutative diagram of schemes
$$
\vcenter{
\xymatrix{
X' \ar[d]_{g'} \ar[r]_{f'} & Y' \ar[d]^g \\
X \ar[r]^f & Y
}
}
\quad\text{with points}\quad
\vcenter{
\xymatrix{
x' \ar[d] \ar[r] & y' \ar[d] \\
x \ar[r] & y
}
}
$$
such that $g$ is smooth $y'$ and $X' \to X \times_Y Y'$ is \'etale
at $x'$, then $x \in W(f) \Leftrightarrow x' \in W(f')$
where $W(-)$ is as in Lemma \ref{lemma-largest-open-of-the-source}.

\label{lemma-characterize-geometrically-irreducible}
\begin{slogan}
Geometric irreducibility can be tested over a separable algebraic
closure of the base field.
\end{slogan}
Let $k$ be a field. Let $X$ be a scheme over $k$.
The following are equivalent:
\begin{enumerate}
\item $X$ is geometrically irreducible over $k$,
\item for every finite separable field extension $k'/k$
the scheme $X_{k'}$ is irreducible, and
\item $X_{\overline{k}}$ is irreducible, where $k \subset \overline{k}$
is a separable algebraic closure of $k$.
\end{enumerate}

\label{lemma-construct-multiplicative-system}
Let $\mathcal{D}$ be a triangulated category.
Let $\mathcal{D}' \subset \mathcal{D}$ be a full triangulated
subcategory. Set
\begin{equation}
\label{equation-multiplicative-system}
S =
\left\{
\begin{matrix}
f \in \text{Arrows}(\mathcal{D})
\text{ such that there exists a distinguished triangle }\\
(X, Y, Z, f, g, h) \text{ of }\mathcal{D}\text{ with }
Z\text{ isomorphic to an object of }\mathcal{D}'
\end{matrix}
\right\}
\end{equation}
Then $S$ is a multiplicative system compatible with the triangulated
structure on $\mathcal{D}$. In this situation the following are equivalent
\begin{enumerate}
\item $S$ is a saturated multiplicative system,
\item $\mathcal{D}'$ is a saturated triangulated subcategory.
\end{enumerate}

\label{lemma-epimorphism-universal-abelian-category}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If $x \to y$ is surjective, then for every $z \to y$ the
projection $x \times_y z \to z$ is surjective.
\item If $x \to y$ is injective, then for every $x \to z$ the
morphism $z \to z \amalg_x y$ is injective.
\end{enumerate}

\label{lemma-characterize-injective}
Let $f : x \to y$ be a morphism in an abelian category $\mathcal{A}$. Then
\begin{enumerate}
\item $f$ is injective if and only if $f$ is a monomorphism,
\item $f$ is surjective if and only if $f$ is an epimorphism, and
\item $f$ is an isomorphism if and only if $f$ is injective and surjective.
\end{enumerate}

\label{proposition-effective}
Let $f : X \to S$ be a surjective integral morphism.
The functor (\ref{equation-descent-etale}) induces an equivalence
$$
\begin{matrix}
\text{schemes quasi-compact,}\\
\text{separated, \'etale over }S
\end{matrix}
\longrightarrow
\begin{matrix}
\text{descent data }(V, \varphi)\text{ relative to }X/S\text{ with}\\
V\text{ quasi-compact, separated, \'etale over }X
\end{matrix}
$$

\label{theorem-structure-unramified}
Let $f : A \to B$ be an unramified morphism of local rings.
Then there exist $f, g \in A[t]$ such that
\begin{enumerate}
\item $B' = A[t]_g/(f)$ is standard \'etale -- see (a) and (b) above, and
\item $B$ is isomorphic to a quotient of a localization of $B'$ at a prime.
\end{enumerate}

\label{lemma-locally-quasi-finite-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally quasi-finite''
is \'etale local on the source.

\label{lemma-flat-finitely-presented-permanence}
\begin{reference}
\cite[IV, 17.7.5 (i) and (ii)]{EGA}.
\end{reference}
Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& S
}
$$
be a commutative diagram of morphisms of schemes. Assume that $f$ is
surjective, flat and locally of finite presentation and assume
that $p$ is locally of finite presentation (resp.\ locally of finite type).
Then $q$ is locally of finite presentation (resp.\ locally of finite type).

\label{lemma-relative-regular-immersion-flat-in-neighbourhood}
Let $X \to S$ be a morphism of schemes.
Let $Z \to X$ be an immersion.
Assume
\begin{enumerate}
\item $X \to S$ is flat and locally of finite presentation,
\item $Z \to X$ is a relative quasi-regular immersion.
\end{enumerate}
Then $Z \to X$ is a regular immersion and
the same remains true after any base change.

\label{lemma-make-Jacobson}
Let $X$ be a scheme over a field $k$.
For any field extension $K/k$ whose cardinality is large enough
we have
\begin{enumerate}
\item for any closed point $x \in X_K$ the extension $\kappa(x)/K$
is algebraic, and
\item $X_K$ is a Jacobson scheme
(Properties, Definition \ref{properties-definition-jacobson}).
\end{enumerate}

\label{lemma-limit-sheaf}
\begin{slogan}
Limit of diagram of sheaves exists and coincides with limit as presheaves
\end{slogan}
Let $\mathcal{F} : \mathcal{I} \to \Sh(\mathcal{C})$
be a diagram. Then $\lim_\mathcal{I} \mathcal{F}$ exists
and is equal to the limit in the category of presheaves.

\label{lemma-weil-divisor-is-cartier-UFD}
Let $X$ be a locally Noetherian scheme. Let $D \subset X$ be an integral
closed subscheme. Assume that
\begin{enumerate}
\item $D$ has codimension $1$ in $X$, and
\item $\mathcal{O}_{X, x}$ is a UFD for all $x \in D$.
\end{enumerate}
Then $D$ is an effective Cartier divisor.

\label{lemma-adjoint-preserve-injectives}
\begin{slogan}
A functor with an exact left adjoint preserves injectives
\end{slogan}
Let $\mathcal{A}$ and $\mathcal{B}$ be abelian categories.
Let $u : \mathcal{A} \to \mathcal{B}$ and
$v : \mathcal{B} \to \mathcal{A}$ be additive functors with
$u$ right adjoint to $v$. Consider the following conditions:
\begin{enumerate}
\item[(a)] $v$ transforms injective maps into injective maps,
\item[(b)] $v$ is exact, and
\item[(c)] $u$ transforms injectives into injectives.
\end{enumerate}
Then (a) $\Leftrightarrow$ (b) $\Rightarrow$ (c). If $\mathcal{A}$
has enough injectives, then all three conditions are equivalent.

\label{theorem-descend-algebra-properties}
If $A \otimes_R S$ has one of the following properties as an $S$-algebra
\begin{enumerate}
\item[(a)]
of finite type;
\item[(b)]
of finite presentation;
\item[(c)]
formally unramified;
\item[(d)]
unramified;
\item[(e)]
\'etale;
\end{enumerate}
then so does $A$ as an $R$-algebra (and of course conversely).

\label{lemma-colimits}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
The category of quasi-coherent modules on $(U, R, s, t, c)$ has colimits.

\label{lemma-fs-local}
Let $(R, \mathfrak m) \to (S, \mathfrak n)$ be a local homomorphism
of local rings. The following are equivalent
\begin{enumerate}
\item $R \to S$ is formally smooth in the $\mathfrak n$-adic topology,
\item for every solid commutative diagram
$$
\xymatrix{
S \ar[r] \ar@{-->}[rd] & A/J \\
R \ar[r] \ar[u] & A \ar[u]
}
$$
of local homomorphisms of local rings where $J \subset A$ is
an ideal of square zero, $\mathfrak m_A^n = 0$ for some $n > 0$, and
$S \to A/J$ induces an isomorphism on residue fields, a dotted
arrow exists which makes the diagram commute.
\end{enumerate}
If $S$ is Noetherian these conditions are also equivalent to
\begin{enumerate}
\item[(3)] same as in (2) but only for diagrams where in addition
$A \to A/J$ is a small extension
(Algebra, Definition \ref{algebra-definition-small-extension}).
\end{enumerate}

\label{lemma-relative-regular-immersion-algebra}
Let $A \to B$ and $A \to A'$ be ring maps. Set $B' = B \otimes_A A'$.
Let $f_1, \ldots, f_r \in B$. Assume $B/(f_1, \ldots, f_r)B$ is flat over $A$
\begin{enumerate}
\item If $f_1, \ldots, f_r$ is a quasi-regular sequence, then
the image in $B'$ is a quasi-regular sequence.
\item If $f_1, \ldots, f_r$ is a $H_1$-regular sequence, then
the image in $B'$ is a $H_1$-regular sequence.
\end{enumerate}

\label{lemma-pullback-representable-presheaf}
Let $u : \mathcal{C} \to \mathcal{D}$ be a functor between categories.
For any object $U$ of $\mathcal{C}$ we have $u_ph_U = h_{u(U)}$.

\label{lemma-independence-of-generators}
Let $R$ be a ring. Let $I$ be an ideal generated by $f_1, \ldots, f_r \in R$.
\begin{enumerate}
\item If $I$ can be generated by a quasi-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is a quasi-regular sequence.
\item If $I$ can be generated by an $H_1$-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is an $H_1$-regular sequence.
\item If $I$ can be generated by a Koszul-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is a Koszul-regular sequence.
\end{enumerate}

\label{proposition-etale-normal}
\begin{reference}
\cite[Expose I, Theorem 9.5 part (i)]{SGA1}
\end{reference}
Let $A$, $B$ be Noetherian local rings.
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then $A$ is a normal domain if and only if $B$ is so.

\label{lemma-criterion-points}
Let $\mathcal{C}$ be a site. Let $I$ be a set and for
$i \in I$ let $U_i$ be an object of $\mathcal{C}$ such that
\begin{enumerate}
\item $\coprod h_{U_i}$ surjects onto
the final object of $\Sh(\mathcal{C})$, and
\item $\mathcal{C}/U_i$ satisfies the hypotheses of
Proposition \ref{proposition-criterion-points}.
\end{enumerate}
Then $\mathcal{C}$ has enough points.

\label{lemma-unbounded-left-derived}
Let $F : \mathcal{A} \to \mathcal{B}$ be a right exact functor of
abelian categories. If
\begin{enumerate}
\item every object of $\mathcal{A}$ is a quotient of an object
which is left acyclic for $F$,
\item there exists an integer $n \geq 0$ such that $L^nF = 0$,
\end{enumerate}
Then
\begin{enumerate}
\item $LF : D(\mathcal{A}) \to D(\mathcal{B})$ exists,
\item any complex consisting of left acyclic objects for $F$ computes $LF$,
\item any complex is the target of a quasi-isomorphism from a complex
consisting of left acyclic objects for $F$,
\item for $E \in D(\mathcal{A})$
\begin{enumerate}
\item $H^i(LF(\tau_{\leq a + n - 1}E) \to H^i(LF(E))$ is an isomorphism
for $i \leq a$,
\item $H^i(LF(E)) \to H^i(LF(\tau_{\geq b}E))$ is an isomorphism
for $i \geq b$,
\item if $H^i(E) = 0$ for $i \not \in [a, b]$ for some
$-\infty \leq a \leq b \leq \infty$, then $H^i(LF(E)) = 0$
for $i \not \in [a - n + 1, b]$.
\end{enumerate}
\end{enumerate}

\label{lemma-flat-finite-type-valuation-ring-finite-presentation}
\begin{reference}
\cite[Theorem 3]{Nagata-Finitely}
\end{reference}
Let $A$ be a valuation ring. Let $A \to B$ be a ring map of finite type.
Let $M$ be a finite $B$-module.
\begin{enumerate}
\item If $B$ is flat over $A$, then $B$ is a finitely presented $A$-algebra.
\item If $M$ is flat as an $A$-module, then $M$ is finitely presented
as a $B$-module.
\end{enumerate}

\label{lemma-graded}
Let $\mathcal{A}$ be an abelian category. The category of graded objects
$\text{Gr}(\mathcal{A})$ is abelian.

\label{lemma-char-p-differentials-free-smooth}
Let $k$ be a field. Let $X$ be a scheme over $k$.
Assume
\begin{enumerate}
\item $X$ is locally of finite type over $k$,
\item $\Omega_{X/k}$ is locally free,
\item $X$ is reduced, and
\item $k$ is perfect.
\end{enumerate}
Then the structure morphism $X \to \Spec(k)$ is smooth.

\label{lemma-dim-1-proper-projective}
Let $X$ be a proper scheme over a field $k$.
If $\dim(X) \leq 1$ then $X$ is H-projective over $k$.

\label{lemma-solution-in-finite-case}
In Situation \ref{situation-locally-given} assume
\begin{enumerate}
\item $X = U_1 \cup \ldots \cup U_n$ with $U_i \in \mathcal{B}$,
\item for $U, V \in \mathcal{B}$ we have
$U \cap V = \bigcup_{W \in \mathcal{B}, W \subset U \cap V} W$,
\item for any $U \in \mathcal{B}$ we have $\Ext^i(K_U, K_U) = 0$
for $i < 0$.
\end{enumerate}
Then a solution exists and is unique up to unique isomorphism.

\label{lemma-semi-local-both-side}
In Situation \ref{situation-glue} assume
\begin{enumerate}
\item $A$ is a Noetherian semi-local domain of dimension $1$,
\item $B$ is a Noetherian semi-local domain of dimension $1$,
\item $A \otimes B \to K$ is surjective.
\end{enumerate}
Then $\Spec(A) \to \Spec(R)$ and $\Spec(B) \to \Spec(R)$
are open immersions covering $\Spec(R)$ and $K = A \otimes_R B$.

\label{lemma-cut-by-koszul}
Let $A' \to B'$ be a ring map. Let $I \subset A'$ be an ideal.
Set $A = A'/I$ and $B = B'/IB'$. Let $f'_1, \ldots, f'_r \in B'$. Assume
\begin{enumerate}
\item $A' \to B'$ is flat and of finite presentation (for example smooth),
\item $I$ is locally nilpotent,
\item the images $f_1, \ldots, f_r \in B$ form a quasi-regular sequence,
\item $B/(f_1, \ldots, f_r)$ is smooth over $A$.
\end{enumerate}
Then $B'/(f'_1, \ldots, f'_r)$ is smooth over $A'$.

\label{lemma-coproduct-quasi-compact}
\begin{slogan}
Finite copoducts of sheaves conserve quasi-compactness.
\end{slogan}
Let $\mathcal{C}$ be a site. If $n \geq 1$ and
$\mathcal{F}_1, \ldots, \mathcal{F}_n$ are quasi-compact
sheaves on $\mathcal{C}$, then $\coprod_{i = 1, \ldots, n} \mathcal{F}_i$
is quasi-compact.

\label{lemma-inseparable-deg-p-smooth}
Let $k$ be a field of characteristic $p > 0$. Let $X$ be a variety over $k$.
The following are equivalent
\begin{enumerate}
\item $X^{(p)}$ is reduced,
\item $X$ is geometrically reduced,
\item there is a nonempty open $U \subset X$ smooth over $k$.
\end{enumerate}
In this case $X^{(p)}$ is a variety over $k$ and $F_{X/k} : X \to X^{(p)}$
is a finite dominant morphism of degree $p^{\dim(X)}$.

\label{lemma-flat-descent-flat-at-primes}
In Situation \ref{situation-flattening-general}
let $R' \to R''$ be an $R$-algebra map.
Let $I' \subset R'$ and $I'R'' \subset I'' \subset R''$ be ideals.
Assume
\begin{enumerate}
\item the map $V(I'') \to V(I')$ induced by
$\Spec(R'') \to \Spec(R')$ is surjective, and
\item $R''_{\mathfrak p''}$ is flat over $R'$ for all primes
$\mathfrak p'' \in V(I'')$.
\end{enumerate}
If (\ref{equation-flat-at-primes}) holds for
$(R'', I'')$, then (\ref{equation-flat-at-primes}) holds for $(R', I')$.

\label{lemma-cohomology-homological}
Let $\mathcal{A}$ be an abelian category. The functor
$$
H^0 : K(\mathcal{A}) \longrightarrow \mathcal{A}
$$
is homological.

\label{lemma-when-shriek}
\begin{slogan}
Sheafification is redundant in topoi morphisms associated to simultaneously
continuous and cocontinuous site functors.
\end{slogan}
Let $\mathcal{C}$ and $\mathcal{D}$ be sites.
Let $u : \mathcal{C} \to \mathcal{D}$ be a functor.
Assume that
\begin{enumerate}
\item[(a)] $u$ is cocontinuous, and
\item[(b)] $u$ is continuous.
\end{enumerate}
Let $g : \Sh(\mathcal{C}) \to \Sh(\mathcal{D})$
be the associated morphism of topoi. Then
\begin{enumerate}
\item sheafification in the formula $g^{-1} = (u^p\ )^\#$ is
unnecessary, in other words $g^{-1}(\mathcal{G})(U) = \mathcal{G}(u(U))$,
\item $g^{-1}$ has a left adjoint $g_{!} = (u_p\ )^\#$, and
\item $g^{-1}$ commutes with arbitrary limits and colimits.
\end{enumerate}

\label{lemma-blow-up-effective-Cartier-divisor}
Let $X$ be a scheme. Let $Z \subset X$ be an effective Cartier divisor.
The blowup of $X$ in $Z$ is the identity morphism of $X$.

\label{lemma-dedekind-torsion-free-flat}
Let $A$ be a Dedekind domain (for example a discrete valuation ring
or more generally a PID).
\begin{enumerate}
\item An $A$-module is flat if and only if it is torsion free.
\item A finite torsion free $A$-module is finite locally free.
\item A finite torsion free $A$-module is finite free if
$A$ is a PID.
\end{enumerate}

\label{lemma-homotopy-s-Q}
\begin{slogan}
The (cosimplicial) Dold-Kan functor carries homotopic maps to homotopic maps.
\end{slogan}
Let $\mathcal{A}$ be an additive category. Let $a, b : U \to V$ be morphisms
of cosimplicial objects of $\mathcal{A}$. If $a$, $b$ are homotopic,
then $s(a), s(b) : s(U) \to s(V)$ are homotopic maps of cochain complexes.
If in addition $\mathcal{A}$ is abelian, then $Q(a), Q(b) : Q(U) \to Q(V)$
are homotopic maps of cochain complexes.

\label{lemma-open-mapping}
Let $u : N \to M$ be a continuous map of topologized
abelian groups. Assume that $M$ separated and that $N$ is complete, linearly
topologized, and has a countable fundamental system of neighbourhoods of $0$.
Then exactly one of the following holds
\begin{enumerate}
\item $u$ is open, or
\item for some open subgroup $N' \subset N$ the image
$u(N')$ is nowhere dense in $M$.
\end{enumerate}

\label{lemma-relative-finitely-presented-module-over-fibre-product}
Let $A, A', B, B', C, C', D, D', I, M', M, N, \varphi$ be as in
Lemma \ref{lemma-relative-module-over-fibre-product}. If
\begin{enumerate}
\item $N$ is finitely presented over $D$ and flat over $B$,
\item $M'$ finitely presented over $C'$ and flat over $A'$, and
\item the ring map $B' \to D'$ factors as $B' \to D'' \to D'$
with $B' \to D''$ flat and $D'' \to D'$ of finite presentation,
\end{enumerate}
then $N' = N \times_M M'$ is finitely presented over $D'$.

\label{lemma-descending-property-isomorphism}
The property $\mathcal{P}(f) =$``$f$ is an isomorphism''
is fpqc local on the base.

\label{lemma-reflexive-over-regular-dim-2}
Let $X$ be a regular scheme of dimension $\leq 2$.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item $\mathcal{F}$ is finite locally free.
\end{enumerate}

\label{lemma-koszul-regular-H1-regular}
A $M$-Koszul-regular sequence is $M$-$H_1$-regular.
A Koszul-regular sequence is $H_1$-regular.

\label{lemma-regular-permanence}
Let $A \to B \to C$ be ring maps. If $A \to C$ is regular and $B \to C$
is flat and surjective on spectra, then $A \to B$ is regular.

\label{lemma-group-scheme-addition-tangent-vectors}
Let $S$ be a scheme. Let $G$ be a group scheme over $S$.
Let $s \in S$. Then the composition
$$
T_{G/S, e(s)} \oplus T_{G/S, e(s)} = T_{G \times_S G/S, (e(s), e(s))}
\rightarrow T_{G/S, e(s)}
$$
is addition of tangent vectors. Here the $=$ comes from
Varieties, Lemma \ref{varieties-lemma-tangent-space-product}
and the right arrow is induced from $m : G \times_S G \to G$ via
Varieties, Lemma \ref{varieties-lemma-map-tangent-spaces}.

\label{lemma-dimension-local-ring-fibre}
Let $d \in \{0, 1, 2, \ldots, \infty\}$.
The property of morphisms of germs
$$
\mathcal{P}_d((X, x) \to (S, s)) =
\text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre has dimension }d
$$
is \'etale local on the source-and-target.

\label{lemma-image-connected-component}
\begin{reference}
Email from Ofer Gabber dated June 4, 2016
\end{reference}
Let $K/k$ be an extension of fields. Let $X$ be a scheme over $k$.
Denote $p : X_K \to X$ the projection morphism.
Let $\overline{T} \subset X_K$ be a connected component.
Then $p(\overline{T})$ is a connected component of $X$.

\label{lemma-compute-pullback-to-limit}
In Situation \ref{situation-inverse-limit-sites} let
$u_i : \mathcal{C}_i \to \mathcal{C}$ be as constructed in
Lemma \ref{lemma-colimit-sites}. Then $u_i$ defines a morphism
of sites $f_i : \mathcal{C} \to \mathcal{C}_i$. For
$U_i \in \Ob(\mathcal{C}_i)$ and sheaf $\mathcal{F}$ on $\mathcal{C}_i$ we have
\begin{equation}
\label{equation-compute-pullback-to-limit}
f_i^{-1}\mathcal{F}(u_i(U_i)) =
\colim_{a : j \to i} f_a^{-1}\mathcal{F}(u_a(U_i))
\end{equation}

\label{lemma-reflexive-depth-2}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item for each $x \in X$ one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module, or
\item $\text{depth}(\mathcal{F}_x) \geq 2$.
\end{enumerate}
\end{enumerate}

\label{lemma-regular-section-structure-sheaf}
Let $X$ be a locally ringed space. Let $f \in \Gamma(X, \mathcal{O}_X)$.
The following are equivalent:
\begin{enumerate}
\item $f$ is a regular section, and
\item for any $x \in X$ the image $f \in \mathcal{O}_{X, x}$
is a nonzerodivisor.
\end{enumerate}
If $X$ is a scheme these are also equivalent to
\begin{enumerate}
\item[(3)] for any affine open $\Spec(A) = U \subset X$
the image $f \in A$ is a nonzerodivisor,
\item[(4)] there exists an affine open covering
$X = \bigcup \Spec(A_i)$ such that
the image of $f$ in $A_i$ is a nonzerodivisor for all $i$.
\end{enumerate}

\label{lemma-enough-points-local}
Let $\mathcal{C}$ be a site. Let $\{U_i\}_{i \in I}$ be a family of
objects of $\mathcal{C}$. Assume
\begin{enumerate}
\item $\coprod h_{U_i}^\# \to *$ is a surjective map of sheaves, and
\item each localization $\mathcal{C}/U_i$ has enough points.
\end{enumerate}
Then $\mathcal{C}$ has enough points.

\label{lemma-four-lemma}
Let $\mathcal{A}$ be an abelian category. Let
$$
\xymatrix{
w \ar[r] \ar[d]^\alpha & x \ar[r] \ar[d]^\beta & y \ar[r] \ar[d]^\gamma &
z \ar[d]^\delta \\
w' \ar[r] & x' \ar[r] & y' \ar[r] & z'
}
$$
be a commutative diagram with exact rows.
\begin{enumerate}
\item If $\alpha, \gamma$ are surjective and $\delta$ is injective, then
$\beta$ is surjective.
\item If $\beta, \delta$ are injective and $\alpha$ is surjective, then
$\gamma$ is injective.
\end{enumerate}

\label{lemma-characterize-open-immersion}
Let $f : X \to Y$ be a morphism of schemes. Let $X^0$ denote the set
of generic points of irreducible components of $X$. If
\begin{enumerate}
\item $f$ is \'etale and separated,
\item for $\xi \in X^0$ we have $\kappa(f(\xi)) = \kappa(\xi)$, and
\item if $\xi, \xi' \in X^0$, $\xi \not = \xi'$, then $f(\xi) \not = f(\xi')$,
\end{enumerate}
then $f$ is an open immersion.

\label{lemma-automorphism}
Let $X$ be a reduced scheme of finite type over a field $k$. Let $f : X \to X$
be an automorphism over $k$ which induces the identity map on the underlying
topological space of $X$. Then
\begin{enumerate}
\item $f^*\mathcal{F} \cong \mathcal{F}$ for every coherent
$\mathcal{O}_X$-module, and
\item if $\dim(Z) > 0$ for every irreducible component $Z \subset X$,
then $f$ is the identity.
\end{enumerate}

\label{lemma-compute-global-sections}
Let $\mathcal{C}$ be a site. Let $a, b : V \to U$ be objects of $\mathcal{C}$
such that
$$
\xymatrix{
h_V^\# \ar@<1ex>[r] \ar@<-1ex>[r] & h_U^\# \ar[r] & {*}
}
$$
is a coequalizer in $\Sh(\mathcal{C})$. Then
$\Gamma(\mathcal{C}, \mathcal{F})$ is the equalizer of
$a^*, b^* : \mathcal{F}(U) \to \mathcal{F}(V)$.

\label{lemma-conormal-algebra-functorial-flat}
Let
$$
\xymatrix{
Z \ar[r]_i \ar[d]_f & X \ar[d]^g \\
Z' \ar[r]^{i'} & X'
}
$$
be a fibre product diagram in the category of schemes with
$i$, $i'$ immersions. Then the canonical map
$f^*\mathcal{C}_{Z'/X', *} \to \mathcal{C}_{Z/X, *}$ of
Lemma \ref{lemma-conormal-algebra-functorial}
is surjective. If $g$ is flat, then it is an isomorphism.

\label{lemma-rank-tensor}
Let $R$ be a domain. Let $M$ and $N$ be $R$-modules.
\begin{enumerate}
\item The rank of $M \otimes_R N$ is the product of the
ranks of $M$ and $N$.
\item If $M$ is a finitely presented $R$-module, then
the rank of $\Hom_R(M, N)$ is the product of the
ranks of $M$ and $N$.
\end{enumerate}

\label{lemma-fully-faithful}
In the situation of Lemma \ref{lemma-pullback}
assume
\begin{enumerate}
\item $\{f : X' \to X\}$ is an fpqc covering (for example if $f$ is
surjective, flat, and quasi-compact), and
\item $S = S'$.
\end{enumerate}
Then the pullback functor is fully faithful.

\label{lemma-topology-basic}
Let $\mathcal{C}$ be a category.
Let $J$ be a topology on $\mathcal{C}$.
Let $U \in \Ob(\mathcal{C})$.
\begin{enumerate}
\item Finite intersections of elements of $J(U)$ are in $J(U)$.
\item If $S \in J(U)$ and $S' \supset S$, then $S' \in J(U)$.
\end{enumerate}

\label{lemma-henselian-henselian-pair}
Let $I \subset J \subset A$ be ideals of a ring $A$.
The following are equivalent
\begin{enumerate}
\item $(A, I)$ and $(A/I, J/I)$ are henselian pairs, and
\item $(A, J)$ is an henselian pair.
\end{enumerate}

\label{lemma-inverse-systems-abelian}
Let $\mathcal{C}$ be a category.
\begin{enumerate}
\item If $\mathcal{C}$ is an additive category, then the category
of inverse systems with values in $\mathcal{C}$ is an additive category.
\item If $\mathcal{C}$ is an abelian category, then the category
of inverse systems with values in $\mathcal{C}$ is an abelian category.
A sequence $(K_i) \to (L_i) \to (M_i)$ of inverse systems
is exact if and only if each $K_i \to L_i \to N_i$ is exact.
\end{enumerate}

\label{lemma-descending-property-integral}
The property $\mathcal{P}(f) =$``$f$ is integral''
is fpqc local on the base.

\label{lemma-quasi-compact}
Let $\mathcal{C}$ be a site. Let $U$ be an object of $\mathcal{C}$.
The following are equivalent
\begin{enumerate}
\item $U$ is quasi-compact, and
\item for every surjection of sheaves
$\coprod_{i \in I} \mathcal{F}_i \to h_U^\#$
there is a finite subset $J \subset I$ such that
$\coprod_{i \in J} \mathcal{F}_i \to h_U^\#$ is surjective.
\end{enumerate}

\label{lemma-open-subtopos}
Let $\mathcal{C}$ be a site. Let $\mathcal{F}$ be a sheaf on
$\mathcal{C}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a subobject of the final object of
$\Sh(\mathcal{C})$, and
\item the topos $\Sh(\mathcal{C})/\mathcal{F}$ is a subtopos of
$\Sh(\mathcal{C})$.
\end{enumerate}

\label{lemma-injective-tangent-spaces-unramified}
Let $f : X \to Y$ be a morphism of schemes locally of finite type over a
base scheme $S$. Let $x \in X$ be a point. Set $y = f(x)$ and assume
that $\kappa(y) = \kappa(x)$. Then the following are equivalent
\begin{enumerate}
\item $\text{d}f : T_{X/S, x} \longrightarrow T_{Y/S, y}$ is injective, and
\item $f$ is unramified at $x$.
\end{enumerate}

\label{lemma-largest-ideal-henselian}
Let $A$ be a ring. There exists a largest ideal $I \subset A$ such that
$(A, I)$ is a henselian pair.

\label{lemma-universal-effective-epimorphism-surjective}
Let $\{f_i : X_i \to X\}_{i \in I}$ be a family of morphisms of schemes.
\begin{enumerate}
\item If the family is universal effective
epimorphism in the category of schemes, then $\coprod f_i$ is surjective.
\item If $X$ and $X_i$ are affine and the family is a universal effective
epimorphism in the category of affine schemes, then
$\coprod f_i$ is surjective.
\end{enumerate}

\label{lemma-idempotents-determined-modulo-radical}
Let $(A, I)$ be a Zariski pair. Then the map from
idempotents of $A$ to idempotents of $A/I$ is injective.

\label{lemma-normal-effective-Cartier-divisor-S1}
Let $X$ be a locally Noetherian normal scheme. Let $D \subset X$ be an
effective Cartier divisor. Then $D$ is $(S_1)$.

\label{lemma-descending-property-locally-finite-type}
The property $\mathcal{P}(f) =$``$f$ is locally of finite type''
is fpqc local on the base.

\label{lemma-morphisms-equal-up-to-homotopy-projective}
Let $\mathcal{A}$ be an abelian category. Consider a solid diagram
$$
\xymatrix{
K^\bullet & L^\bullet \ar[l]^\alpha \\
P^\bullet \ar[u] \ar@{-->}[ru]_{\beta_i}
}
$$
where $P^\bullet$ is bounded above and consists of projective
objects, and $\alpha$ is a quasi-isomorphism.
Any two morphisms $\beta_1, \beta_2$ making the diagram commute
up to homotopy are homotopic.

\label{lemma-helper-finite}
Let $(A, I)$ be a Zariski pair. Let $A \to B$ be a finite ring map.
Assume
\begin{enumerate}
\item $B/IB = B_1 \times B_2$ is a product of $A/I$-algebras
\item $A/I \to B_1/IB_1$ is surjective,
\item $b \in B$ maps to $(1, 0)$ in the product.
\end{enumerate}
Then there exists a monic $f \in A[x]$ with $f(b) = 0$ and
$f \bmod I = (x - 1)x^d$ for some $d \geq 1$.

\label{lemma-conormal-sheaf-section-projective-bundle}
Let $X$ be a scheme. Let $\mathcal{E}$ be a quasi-coherent
$\mathcal{O}_X$-module. There is a bijection
$$
\left\{
\begin{matrix}
\text{sections }\sigma\text{ of the } \\
\text{morphism } \mathbf{P}(\mathcal{E}) \to X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{surjections }\mathcal{E} \to \mathcal{L}\text{ where} \\
\mathcal{L}\text{ is an invertible }\mathcal{O}_X\text{-module}
\end{matrix}
\right\}
$$
In this case $\sigma$ is a closed immersion and there is a canonical
isomorphism
$$
\Ker(\mathcal{E} \to \mathcal{L})
\otimes_{\mathcal{O}_X} \mathcal{L}^{\otimes -1}
\longrightarrow
\mathcal{C}_{\sigma(X)/\mathbf{P}(\mathcal{E})}
$$
Both the bijection and isomorphism are compatible with base change.

\label{lemma-products-sums-shifts-triangles}
Let $\mathcal{D}$ be a pre-triangulated category.
Let $I$ be a set.
\begin{enumerate}
\item Let $X_i$, $i \in I$ be a family of objects of $\mathcal{D}$.
\begin{enumerate}
\item If $\prod X_i$ exists, then $(\prod X_i)[1] = \prod X_i[1]$.
\item If $\bigoplus X_i$ exists, then $(\bigoplus X_i)[1] = \bigoplus X_i[1]$.
\end{enumerate}
\item Let $X_i \to Y_i \to Z_i \to X_i[1]$ be a family of distinguished
triangles of $\mathcal{D}$.
\begin{enumerate}
\item If $\prod X_i$, $\prod Y_i$, $\prod Z_i$ exist, then
$\prod X_i \to \prod Y_i \to \prod Z_i \to \prod X_i[1]$
is a distinguished triangle.
\item If $\bigoplus X_i$, $\bigoplus Y_i$,
$\bigoplus Z_i$ exist, then
$\bigoplus X_i \to \bigoplus Y_i \to \bigoplus Z_i \to \bigoplus X_i[1]$
is a distinguished triangle.
\end{enumerate}
\end{enumerate}

\label{lemma-flat-pullback-torsion}
Let $R \to R'$ be a flat homomorphism of domains. If $M$ is a torsion
free $R$-module, then $M \otimes_R R'$ is a torsion free $R'$-module.

\label{lemma-finite-type-descends-fppf}
Let $f : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$ be a morphism of
locally ringed spaces. Let $\mathcal{F}$ be a sheaf of $\mathcal{O}_Y$-modules.
If
\begin{enumerate}
\item $f$ is open as a map of topological spaces,
\item $f$ is surjective and flat, and
\item $f^*\mathcal{F}$ is of finite type,
\end{enumerate}
then $\mathcal{F}$ is of finite type.

\label{lemma-exact-length-1}
Let $(R, \mathfrak m)$ be a local ring.
Suppose that $\varphi : R^m \to R^n$ is a map
of finite free modules. The following are equivalent
\begin{enumerate}
\item $\varphi$ is injective,
\item the rank of $\varphi$ is $m$ and the annihilator of
$I(\varphi)$ in $R$ is zero.
\end{enumerate}
If $R$ is Noetherian these are also equivalent to
\begin{enumerate}
\item[(3)] the rank of $\varphi$ is $m$ and
either $I(\varphi) = R$ or it contains a nonzerodivisor.
\end{enumerate}
Here the rank of $\varphi$ and $I(\varphi)$ are defined
as in Algebra, Definition \ref{algebra-definition-rank}.

\label{lemma-higher-direct-images-compose}
\begin{slogan}
The total derived functor of a composition is the
composition of the total derived functors.
\end{slogan}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of ringed spaces.
In this case $Rg_* \circ Rf_* = R(g \circ f)_*$ as functors
from $D^{+}(X) \to D^{+}(Z)$.

\label{lemma-syntomic-smooth-etale-permanence}
Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& S
}
$$
be a commutative diagram of morphisms of schemes. Assume that
\begin{enumerate}
\item $f$ is surjective, and syntomic (resp.\ smooth, resp.\ \'etale),
\item $p$ is syntomic (resp.\ smooth, resp.\ \'etale).
\end{enumerate}
Then $q$ is syntomic (resp.\ smooth, resp.\ \'etale).

\label{lemma-flat-relative-H1-regular}
Let $X \to S$ be a morphism of schemes.
Let $Z \to X$ be a relative $H_1$-regular immersion.
Assume $X \to S$ is locally of finite presentation. Then
\begin{enumerate}
\item there exists an open subscheme $U \subset X$ such that
$Z \subset U$ and such that $U \to S$ is flat, and
\item $Z \to X$ is a regular immersion and the same remains
true after any base change.
\end{enumerate}

\label{theorem-plus}
With $\mathcal{F}$ as above
\begin{enumerate}
\item
\label{item-sep}
The presheaf $\mathcal{F}^+$ is separated.
\item
\label{item-sheaf}
If $\mathcal{F}$ is separated, then $\mathcal{F}^+$ is a sheaf
and the map of presheaves $\mathcal{F} \to \mathcal{F}^+$ is injective.
\item
\label{item-plus-iso}
If $\mathcal{F}$ is a sheaf, then $\mathcal{F} \to \mathcal{F}^+$
is an isomorphism.
\item
\label{item-plusplus}
The presheaf $\mathcal{F}^{++}$ is always a sheaf.
\end{enumerate}

\label{lemma-colimit-abelian-category}
Let $\mathcal{A}$ be an abelian category.
All finite limits and finite colimits exist in $\mathcal{A}$.

\label{lemma-group-scheme-module-differentials}
\begin{reference}
\cite[Proposition 3.15]{BookAV}
\end{reference}
Let $(G, m, e, i)$ be a group scheme over the scheme $S$.
Denote $f : G \to S$ the structure morphism.
Then there exist canonical isomorphisms
$$
\Omega_{G/S} \cong f^*\mathcal{C}_{S/G} \cong f^*e^*\Omega_{G/S}
$$
where $\mathcal{C}_{S/G}$ denotes the conormal sheaf of the
immersion $e$. In particular, if $S$ is the spectrum of a field, then
$\Omega_{G/S}$ is a free $\mathcal{O}_G$-module.

\label{lemma-maps-postnikov-systems-vanishing}
Let $\mathcal{D}$ be a triangulated category. Given a map
(\ref{equation-map-complexes}) consider the condition
\begin{equation}
\label{equation-P}
\Hom(X_i[i - j - 1], X'_j) = 0 \text{ for }i > j + 1
\end{equation}
Then
\begin{enumerate}
\item If we have a Postnikov system for
$X'_n \to X'_{n - 1} \to \ldots \to X'_0$ then
property (\ref{equation-P}) implies that
$$
\Hom(X_i[i - j - 1], Y'_j) = 0 \text{ for }i > j + 1
$$
\item If we are given Postnikov systems for both complexes and
we have (\ref{equation-P}), then the map extends to a (nonunique) map
of Postnikov systems.
\end{enumerate}

\label{lemma-cup-product-associative}
Let $f : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$
be a morphism of ringed spaces. The relative cup product of
Remark \ref{remark-cup-product} is associative in the sense that
the diagram
$$
\xymatrix{
Rf_*K \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*L \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*M \ar[r] \ar[d] &
Rf_*(K \otimes_{\mathcal{O}_X}^\mathbf{L} L)
\otimes_{\mathcal{O}_Y}^\mathbf{L} Rf_*M \ar[d] \\
Rf_*K \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*(L \otimes_{\mathcal{O}_X}^\mathbf{L} M) \ar[r] &
Rf_*(K \otimes_{\mathcal{O}_X}^\mathbf{L} 
L \otimes_{\mathcal{O}_X}^\mathbf{L} M)
}
$$
is commutative in $D(\mathcal{O}_Y)$ for all $K, L, M$ in $D(\mathcal{O}_X)$.

\label{lemma-char-zero-differentials-free-smooth}
Let $k$ be a field. Let $X$ be a scheme over $k$.
Assume
\begin{enumerate}
\item $X$ is locally of finite type over $k$,
\item $\Omega_{X/k}$ is locally free, and
\item $k$ has characteristic zero.
\end{enumerate}
Then the structure morphism $X \to \Spec(k)$ is smooth.

\label{lemma-reflexive-torsion-free}
Let $R$ be a domain and let $M$ be an $R$-module.
\begin{enumerate}
\item If $M$ is reflexive, then $M$ is torsion free.
\item If $M$ is finite, then the kernel and cokernel of
$j : M \to \Hom_R(\Hom_R(M, R), R)$ are torsion modules.
\item If $M$ is finite, then $j$ is injective
if and only if $M$ is torsion free.
\end{enumerate}

\label{lemma-construct-absolute-integral-closure}
For any ring $A$ there exists an extension $A \subset B$ such that
\begin{enumerate}
\item $B$ is a filtered colimit of finite free $A$-algebras,
\item $B$ is free as an $A$-module, and
\item $B$ is absolutely integrally closed.
\end{enumerate}

\label{lemma-when-jshriek-compact}
Let $X$ be a ringed space. Let $j : U \to X$ be the
inclusion of an open. The $\mathcal{O}_X$-module $j_!\mathcal{O}_U$ is a
compact object of $D(\mathcal{O}_X)$ if there exists an integer $d$ such that
\begin{enumerate}
\item $H^p(U, \mathcal{F}) = 0$ for all $p > d$, and
\item the functors $\mathcal{F} \mapsto H^p(U, \mathcal{F})$
commute with direct sums.
\end{enumerate}

\label{lemma-regular-field-extension}
Let $K/k$ be a field extension. Then $k \to K$ is a regular
ring map if and only if $K$ is a separable field extension of $k$.

\label{lemma-smooth-permanence}
Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& S
}
$$
be a commutative diagram of morphisms of schemes. Assume that
\begin{enumerate}
\item $f$ is surjective, flat, and locally of finite presentation,
\item $p$ is smooth (resp.\ \'etale).
\end{enumerate}
Then $q$ is smooth (resp.\ \'etale).

\label{lemma-closed-subgroup-scheme}
Let $S$ be a scheme. Let $(G, m, e, i)$ be a group scheme over $S$.
\begin{enumerate}
\item A closed subscheme $H \subset G$ is a closed subgroup scheme
if and only if $e : S \to G$, $m|_{H \times_S H} : H \times_S H \to G$,
and $i|_H : H \to G$ factor through $H$.
\item An open subscheme $H \subset G$ is an open subgroup scheme
if and only if $e : S \to G$, $m|_{H \times_S H} : H \times_S H \to G$,
and $i|_H : H \to G$ factor through $H$.
\end{enumerate}

\label{lemma-quasi-affine-after-field-extension}
Let $k$ be a field. Let $X$ be a scheme over $k$. If $X_K$ is quasi-affine
for some field extension $K/k$, then $X$ is quasi-affine.

\label{lemma-is-limit}
Let $(X, \mathcal{O}_X)$ be a ringed space. Let $E \in D(\mathcal{O}_X)$.
Assume there exist a function $p(-) : \mathbf{Z} \to \mathbf{Z}$
and a set $\mathcal{B}$ of opens of $X$ such that
\begin{enumerate}
\item every open in $X$ has a covering whose members are
elements of $\mathcal{B}$, and
\item $H^p(U, H^{m - p}(E)) = 0$ for $p > p(m)$ and $U \in \mathcal{B}$.
\end{enumerate}
Then the map $E \to R\lim \tau_{\geq -n} E$ of
Derived Categories, Remark
\ref{derived-remark-map-into-derived-limit-truncations}
is an isomorphism in $D(\mathcal{O}_X)$.

\label{lemma-descending-property-universally-closed}
The property $\mathcal{P}(f) =$``$f$ is universally closed''
is fpqc local on the base.

\label{lemma-product-kan}
Let $X_i \to Y_i$ be a set of Kan fibrations. Then
$\prod X_i \to \prod Y_i$ is a Kan fibration.

\label{lemma-locally-finite-type-Jacobson}
Let $X$ be a scheme which is locally of finite type over $k$.
Then
\begin{enumerate}
\item for any closed point $x \in X$ the extension $\kappa(x)/k$
is algebraic, and
\item $X$ is a Jacobson scheme
(Properties, Definition \ref{properties-definition-jacobson}).
\end{enumerate}

\label{lemma-products-homotopy}
Let $\mathcal{C}$ be a category. Let $T$ be a set. For $t \in T$
let $X_t$, $Y_t$ be simplicial objects of $\mathcal{C}$. Assume
$X = \prod_{t \in T} X_t$ and $Y = \prod_{t \in T} Y_t$ exist.
\begin{enumerate}
\item If $X_t$ and $Y_t$ are homotopy equivalent for all $t \in T$
and $T$ is finite, then $X$ and $Y$ are homotopy equivalent.
\end{enumerate}
For $t \in T$ let $a_t, b_t : X_t \to Y_t$ be morphisms.
Set $a = \prod a_t : X \to Y$ and $b = \prod b_t : X \to Y$.
\begin{enumerate}
\item[(2)] If there exists a homotopy from $a_t$ to $b_t$ for
all $t \in T$, then there exists a homotopy from $a$ to $b$.
\item[(3)] If $T$ is finite and $a_t, b_t : X_t \to Y_t$ for $t \in T$
are homotopic, then $a$ and $b$ are homotopic.
\end{enumerate}

\label{lemma-local-rings-UFD-c1-bijective}
Let $X$ be a locally Noetherian integral scheme. Consider the map
(\ref{equation-c1}) $\Pic(X) \to \text{Cl}(X)$.
The following are equivalent
\begin{enumerate}
\item the local rings of $X$ are UFDs, and
\item $X$ is normal and $\Pic(X) \to \text{Cl}(X)$
is surjective.
\end{enumerate}
In this case $\Pic(X) \to \text{Cl}(X)$ is an isomorphism.

\label{lemma-absolutely-integrally-closed-quotient-localization}
Let $A$ be absolutely integrally closed.
\begin{enumerate}
\item Any quotient ring $A/I$ of $A$ is absolutely integrally closed.
\item Any localization $S^{-1}A$ is absolutely integrally closed.
\end{enumerate}

\label{lemma-colimit-sites}
In Situation \ref{situation-inverse-limit-sites} we can construct
a site $(\mathcal{C}, \text{Cov}(\mathcal{C}))$ as follows
\begin{enumerate}
\item as a category $\mathcal{C} = \colim \mathcal{C}_i$, and
\item $\text{Cov}(\mathcal{C})$ is the union of the images
of $\text{Cov}(\mathcal{C}_i)$ by $u_i : \mathcal{C}_i \to \mathcal{C}$.
\end{enumerate}

\label{lemma-degree-more-than-2g}
\begin{reference}
\cite[Lemma 3]{Jongmin}
\end{reference}
In Situation \ref{situation-Cohen-Macaulay-curve}
assume $X$ is integral and has genus $g$.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
If $\deg(\mathcal{L}) \geq 2g$, then $\mathcal{L}$
is globally generated.

\label{lemma-locally-finite-type-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite type''
is fppf local on the source.

\label{lemma-tor-amplitude-stalk}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $E$ be an object of $D(\mathcal{O}_X)$.
Let $a, b \in \mathbf{Z}$ with $a \leq b$. The following are equivalent
\begin{enumerate}
\item $E$ has tor-amplitude in $[a, b]$.
\item for every $x \in X$ the object $E_x$ of $D(\mathcal{O}_{X, x})$
has tor-amplitude in $[a, b]$.
\end{enumerate}

\label{lemma-sieve-sheafification}
Let $\mathcal{C}$ be a category endowed with a topology $J$.
Let $U$ be an object of $\mathcal{C}$.
Let $S$ be a sieve on $U$. The following are equivalent
\begin{enumerate}
\item The sieve $S$ is a covering sieve.
\item The sheafification $S^\# \to h_U^\#$
of the map $S \to h_U$ is an isomorphism.
\end{enumerate}

\label{lemma-geometrically-connected-criterion}
\begin{reference}
\cite[IV Corollary 4.5.13.1(i)]{EGA}
\end{reference}
Let $k$ be a field. Let $T \to X$ be a morphism of schemes over $k$.
Assume $T$ is geometrically connected and $X$ connected.
Then $X$ is geometrically connected.

\label{lemma-descending-property-finite}
The property $\mathcal{P}(f) =$``$f$ is finite''
is fpqc local on the base.

\label{lemma-characterize-open-immersion}
Let $f : X \to Y$ be a morphism of schemes. Let $X^0$ denote the set
of generic points of irreducible components of $X$. If
\begin{enumerate}
\item $f$ is separated,
\item there is an open covering $X = \bigcup U_i$ such that
$f|_{U_i} : U_i \to Y$ is an open immersion, and
\item if $\xi, \xi' \in X^0$, $\xi \not = \xi'$, then $f(\xi) \not = f(\xi')$,
\end{enumerate}
then $f$ is an open immersion.

\label{lemma-play-with-topologies}
Let $\mathcal{C}$ be a category.
Let $\{J_i\}_{i\in I}$ be a set of topologies.
\begin{enumerate}
\item The rule $J(U) = \bigcap J_i(U)$ defines
a topology on $\mathcal{C}$.
\item There is a coarsest topology finer than
all of the topologies $J_i$.
\end{enumerate}

\label{lemma-weakly-associated-affine-open}
Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $\Spec(A) = U \subset X$ be an affine open, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
The following are equivalent
\begin{enumerate}
\item $\mathfrak p$ is weakly associated to $M$, and
\item $x$ is weakly associated to $\mathcal{F}$.
\end{enumerate}

\label{lemma-smooth-smooth-local-source}
The property $\mathcal{P}(f)=$``$f$ is smooth''
is smooth local on the source.

\label{lemma-locally-Noetherian-K}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item For any $x \in X$ we have $\mathcal{S}_x \subset \mathcal{O}_{X, x}$
is the set of nonzerodivisors, and hence $\mathcal{K}_{X, x}$
is the total quotient ring of $\mathcal{O}_{X, x}$.
\item For any affine open $U \subset X$ the ring
$\mathcal{K}_X(U)$ equals the total quotient ring of $\mathcal{O}_X(U)$.
\end{enumerate}

\label{lemma-j-shriek-reflects-injections-surjections}
Let $\mathcal{C}$ be a site. Let $U \in \Ob(\mathcal{C})$.
The functor $j_{U!}$ reflects injections and surjections.

\label{lemma-tor-strictly-pro-zero}
\begin{reference}
This is \cite[Lemma 9.9]{quillenhomology}; note that
the author forgot the word ``strict'' in the statement
although it was clearly intended.
\end{reference}
Let $A$ be a Noetherian ring. Let $I$ be an ideal of $A$.
Let $M$ be a finite $A$-module. For every $p > 0$ there exists a $c > 0$
such that $\text{Tor}_p^A(M, A/I^n) \to \text{Tor}_p^A(M, A/I^{n - c})$
is zero for all $n \geq c$.

\label{lemma-descending-property-monomorphism}
The property $\mathcal{P}(f) =$``$f$ is a monomorphism''
is fpqc local on the base.

\label{lemma-completion-depth}
Let $A$ be a Noetherian local ring. Then
$\text{depth}(A) = \text{depth}(A^\wedge)$.

\label{lemma-extended-alternating-torsion}
Let $R$ be a ring. Let $f_1, \ldots, f_r \in R$. Let $M$ be an $R$-module.
Let $H^q$ be the $q$th cohomology module of the extended alternation
{\v C}ech complex of $M$. Then
\begin{enumerate}
\item $H^q = 0$ if $q \not \in [0, r]$,
\item for $x \in H^i$ there exists an $n \geq 1$ such that $f_i^n x = 0$
for $i = 1, \ldots, r$,
\item the support of $H^q$ is contained in $V(f_1, \ldots, f_r)$,
\item if there is an $f \in (f_1, \ldots, f_r)$ which acts invertibly
on $M$, then $H^q = 0$.
\end{enumerate}

\label{lemma-descending-property-affine}
The property $\mathcal{P}(f) =$``$f$ is affine''
is fpqc local on the base.

\label{lemma-equalizer-S}
The diagram
\begin{equation}
\label{equation-equalizer-S}
\xymatrix@C=8pc{
S_1 \ar[r]^{\delta^1_1} &
S_2 \ar@<1ex>[r]^{\delta^2_2} \ar@<-1ex>[r]_{\delta^2_1} & 
S_3
}
\end{equation}
is a split equalizer.

\label{proposition-generator-versus-classical-generator}
Let $\mathcal{D}$ be a triangulated category with direct sums.
Let $E$ be a compact object of $\mathcal{D}$.
The following are equivalent
\begin{enumerate}
\item $E$ is a classical generator for $\mathcal{D}_c$ and
$\mathcal{D}$ is compactly generated, and
\item $E$ is a generator for $\mathcal{D}$.
\end{enumerate}

\label{lemma-splitting-simplicial-sets}
Let $U$ be a simplicial set. Then $U$ has a unique splitting
with $N(U_m)$ equal to the set of nondegenerate $m$-simplices.

\label{lemma-dominate-two-surjections}
Let $S \to R$ and $S' \to R$ be surjective maps of complete Noetherian local
rings. Then $S \times_R S'$ is a complete Noetherian local ring.

\label{lemma-change-fields-pic}
Let $k'/k$ be a field extension.
Let $X$ be a scheme over $k$ such that
\begin{enumerate}
\item $X$ is quasi-compact and quasi-separated, and
\item $R = H^0(X, \mathcal{O}_X)$ is semi-local, e.g., if $\dim_k R < \infty$.
\end{enumerate}
Then the pullback map $\Pic(X) \to \Pic(X_{k'})$ is injective.

\label{lemma-open-subgroup-closed-over-field}
Let $k$ be a field. Let $\psi : G' \to G$ be a morphism of group schemes
over $k$. If $\psi(G')$ is open in $G$, then $\psi(G')$ is closed in $G$.

\label{lemma-limit-flat}
Let $A$ be a Noetherian ring. Let $I$ be an ideal of $A$. Let
$(M_n)$ be an inverse system of $A$-modules such that
\begin{enumerate}
\item $M_n$ is a flat $A/I^n$-module,
\item $M_{n + 1} \to M_n$ is surjective.
\end{enumerate}
Then $M = \lim M_n$ is a flat $A$-module and
$Q \otimes_A M = \lim Q \otimes_A M_n$ for every finite $A$-module $Q$.

\label{lemma-relative-surjection-ideals}
In Situation \ref{situation-relative-module-over-fibre-product}
the map $JD' \to IC'$ is surjective where $J = \Ker(B' \to B)$.

\label{lemma-affine-Xs}
Assumptions and notation as in Lemma \ref{lemma-structure-sheaf-Xs}.
The following are equivalent
\begin{enumerate}
\item the inclusion morphism $j : U \to X$ is affine, and
\item for every $x \in X \setminus U$ there is an $n > 0$
such that $s^n \in \mathfrak m_x \mathcal{F}^{[n]}_x$.
\end{enumerate}

\label{lemma-abelian-variety-multiplication-by-d-etale}
\begin{slogan}
Multiplication by an integer on an abelian variety is an etale morphism
if and only if the integer is invertible in the base field.
\end{slogan}
Let $k$ be a field. Let $A$ be a nonzero abelian variety over $k$.
Then $[d] : A \to A$ is \'etale if and only if $d$ is invertible in $k$.

\label{lemma-fitting-ideal-finite-locally-free}
Let $R$ be a ring. Let $M$ be a finite $R$-module. Let $r \geq 0$.
The following are equivalent
\begin{enumerate}
\item $M$ is finite locally free of rank $r$
(Algebra, Definition \ref{algebra-definition-locally-free}),
\item $\text{Fit}_{r - 1}(M) = 0$ and $\text{Fit}_r(M) = R$, and
\item $\text{Fit}_k(M) = 0$ for $k < r$ and $\text{Fit}_k(M) = R$
for $k \geq r$.
\end{enumerate}

\label{lemma-compute-filtered-cohomology}
Let $\mathcal{A}$ be an abelian category. Let $(K, F, d)$ be a filtered
differential object of $\mathcal{A}$. If $Z_\infty^p$ and $B_\infty^p$
exist (see proof), then
\begin{enumerate}
\item the limit $E_\infty$ exists and is graded having
$E_\infty^p = Z_\infty^p/B_\infty^p$ in degree $p$, and
\item the associated graded $\text{gr}(H(K))$ of the cohomology of $K$
is a graded subquotient of the graded limit object $E_\infty$.
\end{enumerate}

\label{lemma-relative-frobenius-omega}
Let $p > 0$ be a prime number. Let $S$ be a scheme in characteristic $p$.
Let $X$ be a scheme over $S$. Then $\Omega_{X/S} = \Omega_{X/X^{(p)}}$.

\label{lemma-flat-tor-zero}
\begin{slogan}
Tor measures the deviation of flatness.
\end{slogan}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a flat $\mathcal{O}_X$-module, and
\item $\text{Tor}_1^{\mathcal{O}_X}(\mathcal{F}, \mathcal{G}) = 0$
for every $\mathcal{O}_X$-module $\mathcal{G}$.
\end{enumerate}

\label{lemma-nodal-family-fpqc-local-target}
Let $f : X \to S$ be a morphism of schemes. Let $\{U_i \to S\}$
be an fpqc covering. The following are equivalent
\begin{enumerate}
\item $f$ is at-worst-nodal of relative dimension $1$,
\item each $X \times_S U_i \to U_i$ is at-worst-nodal of relative
dimension $1$.
\end{enumerate}
In other words, being at-worst-nodal of relative dimension $1$
is fpqc local on the target.

\label{lemma-composition-admissible-blowups}
\begin{slogan}
Admissible blowups are stable under composition.
\end{slogan}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $U \subset X$ be a quasi-compact open subscheme.
Let $b : X' \to X$ be a $U$-admissible blowup.
Let $X'' \to X'$ be a $U$-admissible blowup.
Then the composition $X'' \to X$ is a $U$-admissible blowup.

\label{lemma-regular-ideal-sheaf-quasi-coherent}
Any regular, Koszul-regular, $H_1$-regular, or quasi-regular sheaf
of ideals on a scheme is a finite type quasi-coherent sheaf of ideals.

\label{lemma-open-in-affine-curve-affine}
Let $X$ be an affine scheme all of whose local rings are Noetherian
of dimension $\leq 1$. Then any quasi-compact open $U \subset X$ is affine.

\label{lemma-cup-compatible-with-naive}
In the situation above the following diagram commutes
$$
\xymatrix{
f_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}^\mathbf{L}
f_*\mathcal{M}^\bullet \ar[r] \ar[d]
&
Rf_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*\mathcal{M}^\bullet \ar[d]^{\text{Remark \ref{remark-cup-product}}} \\
\text{Tot}(
f_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}
f_*\mathcal{M}^\bullet) \ar[d]_{\text{naive cup product}} &
Rf_*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_X}^\mathbf{L}
\mathcal{M}^\bullet) \ar[d] \\
f_*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_X}
\mathcal{M}^\bullet) \ar[r] &
Rf_*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_X}
\mathcal{M}^\bullet)
}
$$

\label{lemma-diagram-pull}
Let $S$ be a scheme.
Let $(U, R, s, t, c, e, i)$ be a groupoid over $S$.
The diagram
\begin{equation}
\label{equation-pull}
\xymatrix{
R \times_{t, U, t} R
\ar@<1ex>[r]^-{\text{pr}_1} \ar@<-1ex>[r]_-{\text{pr}_0}
\ar[d]_{(\text{pr}_0, c \circ (i, 1))} &
R \ar[r]^t \ar[d]^{\text{id}_R} &
U \ar[d]^{\text{id}_U} \\
R \times_{s, U, t} R
\ar@<1ex>[r]^-c \ar@<-1ex>[r]_-{\text{pr}_0} \ar[d]_{\text{pr}_1} &
R \ar[r]^t \ar[d]^s &
U \\
R \ar@<1ex>[r]^s \ar@<-1ex>[r]_t &
U
}
\end{equation}
is commutative. The two top rows are isomorphic via the vertical maps given.
The two lower left squares are cartesian.

\label{lemma-genus-zero-positive-degree}
Let $X$ be a proper curve over a field $k$ with $H^0(X, \mathcal{O}_X) = k$.
Assume $X$ has genus $0$. Let $\mathcal{L}$ be an invertible
$\mathcal{O}_X$-module of degree $d > 0$. Then we have
\begin{enumerate}
\item $\dim_k H^0(X, \mathcal{L}) = d + 1$ and $\dim_k H^1(X, \mathcal{L}) = 0$,
\item $\mathcal{L}$ is very ample and defines a closed immersion into
$\mathbf{P}^d_k$.
\end{enumerate}

\label{lemma-kernel-quotient}
Let $\mathcal{D}$ be a triangulated category.
Let $\mathcal{B}$ be a full triangulated subcategory.
The kernel of the quotient functor
$Q : \mathcal{D} \to \mathcal{D}/\mathcal{B}$
is the strictly full subcategory of $\mathcal{D}$ whose objects are
$$
\Ob(\Ker(Q)) =
\left\{
\begin{matrix}
Z \in \Ob(\mathcal{D})
\text{ such that there exists a }Z' \in \Ob(\mathcal{D}) \\
\text{ such that }Z \oplus Z'\text{ is isomorphic to an object of }\mathcal{B}
\end{matrix}
\right\}
$$
In other words it is the smallest strictly full saturated triangulated
subcategory of $\mathcal{D}$ containing $\mathcal{B}$.

\label{lemma-descending-property-flat}
The property $\mathcal{P}(f) =$``$f$ is flat''
is fpqc local on the base.

\label{lemma-descending-property-finite-type}
The property $\mathcal{P}(f) =$``$f$ is of finite type''
is fpqc local on the base.

\label{lemma-smooth-models}
Let $k$ be a field. Let $X$ be a geometrically irreducible curve over $k$.
For a field extension $K/k$ denote $Y_K$ a nonsingular projective model
of $(X_K)_{red}$.
\begin{enumerate}
\item If $X$ is proper, then $Y_K$ is the normalization of $X_K$.
\item There exists $K/k$ finite purely inseparable such that $Y_K$ is smooth.
\item Whenever $Y_K$ is smooth\footnote{Or even geometrically reduced.}
we have $H^0(Y_K, \mathcal{O}_{Y_K}) = K$.
\item Given a commutative diagram
$$
\xymatrix{
\Omega & K' \ar[l] \\
K \ar[u] & k \ar[l] \ar[u]
}
$$
of fields such that $Y_K$ and $Y_{K'}$ are smooth, then
$Y_\Omega = (Y_K)_\Omega = (Y_{K'})_\Omega$.
\end{enumerate}

\label{theorem-flat-is-quotient}
A faithfully flat quasi-compact morphism is a quotient map for
the Zariski topology.

\label{lemma-descending-property-regular-immersion}
The properties
\begin{enumerate}
\item[] $\mathcal{P}(f) =$``$f$ is a Koszul-regular immersion'',
\item[] $\mathcal{P}(f) =$``$f$ is an $H_1$-regular immersion'', and
\item[] $\mathcal{P}(f) =$``$f$ is a quasi-regular immersion''
\end{enumerate}
are fpqc local on the base.

\label{lemma-brown-bis}
\begin{reference}
Weak version of \cite[Theorem A]{Krause}
\end{reference}
Let $\mathcal{D}$ be a triangulated category with direct sums.
Suppose given a set $\mathcal{E}$ of objects of $\mathcal{D}$ such that
\begin{enumerate}
\item if $X$ is a nonzero object of $\mathcal{D}$, then there exists
an $E \in \mathcal{E}$ and a nonzero map $E \to X$, and
\item given objects $X_n$, $n \in \mathbf{N}$ of $\mathcal{D}$,
$E \in \mathcal{E}$, and $\alpha : E \to \bigoplus X_n$,
there exist $E_n \in \mathcal{E}$ and $\beta_n : E_n \to X_n$ and a morphism
$\gamma : E \to \bigoplus E_n$ such that
$\alpha = (\bigoplus \beta_n) \circ \gamma$.
\end{enumerate}
Let $H : \mathcal{D} \to \textit{Ab}$ be a contravariant cohomological functor
which transforms direct sums into products. Then $H$ is representable.

\label{lemma-sum-effective-Cartier-divisors}
The sum of two effective Cartier divisors is an effective
Cartier divisor.

\label{lemma-adjoint-get-abelian}
Let $a : \mathcal{A} \to \mathcal{B}$ and $b : \mathcal{B} \to \mathcal{A}$
be functors. Assume that
\begin{enumerate}
\item $\mathcal{A}$, $\mathcal{B}$ are additive categories,
$a$, $b$ are additive functors, and $a$ is right adjoint to $b$,
\item $\mathcal{B}$ is abelian and $b$ is left exact, and
\item $ba \cong \text{id}_\mathcal{A}$.
\end{enumerate}
Then $\mathcal{A}$ is abelian.

\label{lemma-composition-strict}
Let $\mathcal{A}$ be an abelian category. Let $f : A \to B$, $g : B \to C$
be strict morphisms of filtered objects.
\begin{enumerate}
\item In general the composition $g \circ f$ is not strict.
\item If $g$ is injective, then $g \circ f$ is strict.
\item If $f$ is surjective, then $g \circ f$ is strict.
\end{enumerate}

\label{theorem-etale-radicial-open}
Let $f : X \to Y$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is an open immersion,
\item $f$ is universally injective and \'etale, and
\item $f$ is a flat monomorphism, locally of finite presentation.
\end{enumerate}

\label{lemma-dimension-product-locally-algebraic}
\begin{slogan}
The dimension of the product is the sum of the dimensions.
\end{slogan}
Let $k$ be a field. Let $X$, $Y$ be locally algebraic $k$-schemes.
\begin{enumerate}
\item For $z \in X \times Y$ lying over $(x, y)$ we have
$\dim_z(X \times Y) = \dim_x(X) + \dim_y(Y)$.
\item We have $\dim(X \times Y) = \dim(X) + \dim(Y)$.
\end{enumerate}

\label{lemma-tensor-pull-compatibility}
Let $f : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$ be a morphism
of ringed spaces. Let $\mathcal{K}^\bullet$ and $\mathcal{M}^\bullet$
be complexes of $\mathcal{O}_Y$-modules. The diagram
$$
\xymatrix{
Lf^*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}^\mathbf{L}
\mathcal{M}^\bullet) \ar[r] \ar[d] &
Lf^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}
\mathcal{M}^\bullet) \ar[d] \\
Lf^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}^\mathbf{L}
Lf^*\mathcal{M}^\bullet \ar[d] &
f^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}
\mathcal{M}^\bullet) \ar[d] \\
f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}^\mathbf{L}
f^*\mathcal{M}^\bullet \ar[r] &
\text{Tot}(f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}
f^*\mathcal{M}^\bullet)
}
$$
commutes.

\label{lemma-torsion-free-over-regular-dim-1}
Let $X$ be an integral regular scheme of dimension $\leq 1$.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is torsion free,
\item $\mathcal{F}$ is finite locally free.
\end{enumerate}

\label{lemma-product-trivial-kan}
\begin{slogan}
Products of trivial Kan fibrations are trivial Kan fibrations.
\end{slogan}
Let $X_i \to Y_i$ be a set of trivial Kan fibrations. Then
$\prod X_i \to \prod Y_i$ is a trivial Kan fibration.

\label{lemma-geometrically-irreducible-self-product}
A scheme $X$ over a field $k$ is geometrically irreducible
over $k$ if and only if $X\times_k X$ is irreducible.

\label{lemma-noetherian-dim-1-CM-no-embedded-points}
Let $X$ be a locally Noetherian scheme of dimension $\leq 1$.
The following are equivalent
\begin{enumerate}
\item $X$ is Cohen-Macaulay, and
\item $X$ has no embedded points.
\end{enumerate}

\label{lemma-dim-1-quasi-projective}
Let $X$ be a separated finite type scheme over a field $k$.
If $\dim(X) \leq 1$ then $X$ is H-quasi-projective over $k$.

\label{lemma-plane-curve}
Let $Z \subset \mathbf{P}^2_k$ be as in Lemma \ref{lemma-equation-plane-curve}
and let $I(Z) = (F)$ for some $F \in k[T_0, T_1, T_2]$.
Then $Z$ is a curve if and only if $F$ is irreducible.

\label{lemma-compare-etale-zariski-flat}
In Lemma \ref{lemma-compare-sites} the morphism of ringed
sites $\text{id}_{small, \etale, Zar} : S_\etale \to S_{Zar}$ is flat.

\label{lemma-cone}
The cone on a morphism of strictly perfect complexes is
strictly perfect.

\label{lemma-regular-goes-up}
Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is regular,
\item $S$ is Noetherian, and
\item $R$ is Noetherian and regular.
\end{enumerate}
Then $S$ is regular.

\label{lemma-check-injective-on-weakass}
Let $X$ be a scheme. Let $\varphi : \mathcal{F} \to \mathcal{G}$ be a map of
quasi-coherent $\mathcal{O}_X$-modules. Assume that for every $x \in X$
at least one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x \to \mathcal{G}_x$ is injective, or
\item $x \not \in \text{WeakAss}(\mathcal{F})$.
\end{enumerate}
Then $\varphi$ is injective.

\label{lemma-injective-restriction-surjective}
\begin{slogan}
Injectives are flasque.
\end{slogan}
Let $X$ be a ringed space.
Let $U' \subset U \subset X$ be open subspaces.
For any injective $\mathcal{O}_X$-module $\mathcal{I}$ the
restriction mapping
$\mathcal{I}(U) \to \mathcal{I}(U')$ is surjective.

\label{lemma-characterize-geometrically-disconnected}
Let $k$ be a field.
Let $X$ be a scheme over $k$.
The following are equivalent
\begin{enumerate}
\item $X$ is geometrically connected,
\item for every finite separable field extension $k'/k$
the scheme $X_{k'}$ is connected.
\end{enumerate}

\label{lemma-etale-etale-local-source-target}
Let $\mathcal{P}$ be a property of morphisms of schemes which
is \'etale local on the source-and-target.
Given a commutative diagram of schemes
$$
\vcenter{
\xymatrix{
X' \ar[d]_{g'} \ar[r]_{f'} & Y' \ar[d]^g \\
X \ar[r]^f & Y
}
}
\quad\text{with points}\quad
\vcenter{
\xymatrix{
x' \ar[d] \ar[r] & y' \ar[d] \\
x \ar[r] & y
}
}
$$
such that $g'$ is \'etale at $x'$ and $g$ is \'etale at $y'$, then
$x \in W(f) \Leftrightarrow x' \in W(f')$
where $W(-)$ is as in Lemma \ref{lemma-largest-open-of-the-source}.

\label{lemma-make-nonzero-divisor}
\begin{reference}
This is a particular case of \cite[Corollary]{McCoy}
\end{reference}
Let $R$ be a ring. Let $a_1, \ldots, a_n \in R$ be elements such
that $R \to R^{\oplus n}$, $x \mapsto (xa_1, \ldots, xa_n)$ is injective.
Then the element $\sum a_i t_i$ of the polynomial ring $R[t_1, \ldots, t_n]$
is a nonzerodivisor.

\label{lemma-finite-length}
Let $\mathcal{A}$ be an abelian category. Let $A$ be an object
of $\mathcal{A}$. The following are equivalent
\begin{enumerate}
\item $A$ is Artinian and Noetherian, and
\item there exists a filtration
$0 \subset A_1 \subset A_2 \subset \ldots \subset A_n = A$
by subobjects such that $A_i/A_{i - 1}$ is simple for $i = 1, \ldots, n$.
\end{enumerate}

\label{lemma-torsion-free-finite-noetherian-domain}
Let $R$ be a Noetherian domain. Let $M$ be a nonzero finite $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is torsion free,
\item $M$ is a submodule of a finite free module,
\item $(0)$ is the only associated prime of $M$,
\item $(0)$ is in the support of $M$ and $M$ has property $(S_1)$, and
\item $(0)$ is in the support of $M$ and $M$ has no embedded associated prime.
\end{enumerate}

\label{lemma-number-of-branches}
Let $X$ be a scheme. Assume every quasi-compact open of $X$ has
finitely many irreducible components. Let $\nu : X^\nu \to X$
be the normalization of $X$. Let $x \in X$.
\begin{enumerate}
\item The number of branches of $X$ at $x$ is the number of
inverse images of $x$ in $X^\nu$.
\item The number of geometric branches of $X$ at $x$ is
$\sum_{\nu(x^\nu) = x} [\kappa(x^\nu) : \kappa(x)]_s$.
\end{enumerate}

\label{lemma-sheafification-exact}
The functor $\textit{PSh}(\mathcal{C}) \to \Sh(\mathcal{C})$,
$\mathcal{F} \mapsto \mathcal{F}^\#$ is exact.

\label{lemma-descending-property-universally-injective}
The property $\mathcal{P}(f) =$``$f$ is universally injective''
is fpqc local on the base.

\label{lemma-Sk-local-syntomic}
The property $\mathcal{P}(S) =$``$S$ is locally Noetherian and $(S_k)$''
is local in the syntomic topology.

\label{proposition-push-down-ample}
Let $\pi : X \to Y$ be a finite surjective morphism of schemes.
Assume that $X$ has an ample invertible $\mathcal{O}_X$-module. If
\begin{enumerate}
\item $\pi$ is finite locally free, or
\item $Y$ is an integral normal scheme, or
\item $Y$ is Noetherian, $p\mathcal{O}_Y = 0$, and $X = Y_{red}$,
\end{enumerate}
then $Y$ has an ample invertible $\mathcal{O}_Y$-module.

\label{lemma-finite-set-codim-1-points-in-affine-per-component}
Let $X$ be a scheme. Let $T \subset X$ be finite set of points. Assume
\begin{enumerate}
\item $X$ has finitely many irreducible components $Z_1, \ldots, Z_t$, and
\item $Z_i \cap T$ is contained in an affine open of the reduced
induced subscheme corresponding to $Z_i$.
\end{enumerate}
Then there exists an affine open subscheme of $X$ containing $T$.

\label{lemma-cone-pseudo-coherent}
Let $(X, \mathcal{O}_X)$ be a ringed space and $m \in \mathbf{Z}$.
Let $(K, L, M, f, g, h)$ be a distinguished triangle in $D(\mathcal{O}_X)$.
\begin{enumerate}
\item If $K$ is $(m + 1)$-pseudo-coherent and $L$ is $m$-pseudo-coherent
then $M$ is $m$-pseudo-coherent.
\item If $K$ and $M$ are $m$-pseudo-coherent, then $L$ is $m$-pseudo-coherent.
\item If $L$ is $(m + 1)$-pseudo-coherent and $M$
is $m$-pseudo-coherent, then $K$ is $(m + 1)$-pseudo-coherent.
\end{enumerate}

\label{lemma-standard-simplicial}
In Situation \ref{situation-adjoint-functors}
the system $X = (X_n, d^n_j, s^n_j)$
is a simplicial object of $\text{Fun}(\mathcal{A}, \mathcal{A})$
and $\epsilon_0$ defines an augmentation $\epsilon$ from $X$
to the constant simplicial object with value $X_{-1} = \text{id}_\mathcal{A}$.

\label{lemma-closed-immersion-dim-1-CM}
Let $X$ be a proper scheme of dimension $\leq 1$ over a field $k$.
Let $i : Y \to X$ be a closed immersion.
Let $\omega_X^\bullet$, $\omega_X$, $\omega_Y^\bullet$, $\omega_Y$
be as in Lemma \ref{lemma-duality-dim-1}. Then
\begin{enumerate}
\item $\omega_Y^\bullet = R\SheafHom(\mathcal{O}_Y, \omega_X^\bullet)$,
\item $\omega_Y = \SheafHom(\mathcal{O}_Y, \omega_X)$ and
$i_*\omega_Y = \SheafHom_{\mathcal{O}_X}(i_*\mathcal{O}_Y, \omega_X)$.
\end{enumerate}

\label{lemma-nilpotent}
Let $\mathcal{A}$ be an additive category.
Let $0 \to A_i^\bullet \to B_i^\bullet \to C_i^\bullet \to 0$, $i = 1, 2, 3$
be termwise split exact sequences of complexes. Let
$b : B_1^\bullet \to B_2^\bullet$ and $b' : B_2^\bullet \to B_3^\bullet$
be morphisms of complexes such that
$$
\vcenter{
\xymatrix{
A_1^\bullet \ar[d]_0 \ar[r] &
B_1^\bullet \ar[r] \ar[d]_b &
C_1^\bullet \ar[d]_0 \\
A_2^\bullet \ar[r] & B_2^\bullet \ar[r] & C_2^\bullet
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
A_2^\bullet \ar[d]^0 \ar[r] &
B_2^\bullet \ar[r] \ar[d]^{b'} &
C_2^\bullet \ar[d]^0 \\
A_3^\bullet \ar[r] & B_3^\bullet \ar[r] & C_3^\bullet
}
}
$$
commute in $K(\mathcal{A})$. Then $b' \circ b = 0$ in $K(\mathcal{A})$.

\label{lemma-dim-1-noetherian-reduced-separated-has-ample}
Let $X$ be a Noetherian reduced separated scheme of dimension $1$.
Then $X$ has an ample invertible sheaf.

\label{lemma-split-surjection}
Let $R$ be a ring. A morphism $f: M \to N$ in $\text{Mod}_R$ is universally
injective if and only if $C(f): C(N) \to C(M)$ is a split surjection.

\label{lemma-completion-dimension}
Let $A$ be a Noetherian local ring.
Then $\dim(A) = \dim(A^\wedge)$.

\label{lemma-Noetherian-local-fppf}
The property $\mathcal{P}(S) =$``$S$ is locally Noetherian'' is local
in the fppf topology.

\label{lemma-descending-property-syntomic}
The property $\mathcal{P}(f) =$``$f$ is syntomic''
is fpqc local on the base.

\label{lemma-base-change-normal-by-separable}
Let $k$ be a field. Let $X$ be a normal scheme over $k$. Let $K/k$
be a separable field extension. Then $X_K$ is a normal scheme.

\label{lemma-cech-exact-presheaves}
The functor given by Equation (\ref{equation-cech-functor})
is an exact functor (see Homology, Lemma \ref{homology-lemma-exact-functor}).

\label{lemma-CM-local-syntomic}
The property $\mathcal{P}(S) =$``$S$ is Cohen-Macaulay''
is local in the syntomic topology.

\label{lemma-complement-locally-principal-closed-subscheme}
Let $S$ be a scheme. Let $Z \subset S$ be a locally principal closed
subscheme. Let $U = S \setminus Z$. Then $U \to S$ is an affine morphism.

\label{lemma-filtered}
Let $\mathcal{A}$ be an abelian category.
The category of filtered objects $\text{Fil}(\mathcal{A})$
has the following properties:
\begin{enumerate}
\item It is an additive category.
\item It has a zero object.
\item It has kernels and cokernels, images and coimages.
\item In general it is not an abelian category.
\end{enumerate}

\label{lemma-complete-local-ring-structure-as-algebra}
Let $k$ be a field. Let $X$ be a locally Noetherian scheme over $k$.
Let $x \in X$ be a point with residue field $\kappa$.
There is an isomorphism
\begin{equation}
\label{equation-complete-local-ring}
\kappa[[x_1, \ldots, x_n]]/I \longrightarrow \mathcal{O}_{X, x}^\wedge
\end{equation}
inducing the identity on residue fields.
In general we cannot choose (\ref{equation-complete-local-ring})
to be a $k$-algebra isomorphism. However, if the extension $\kappa/k$
is separable, then we can choose
(\ref{equation-complete-local-ring}) to be an isomorphism of $k$-algebras.

\label{lemma-localize-compare}
Let $\mathcal{C}$ be a site. Let $\mathcal{F} = h_U^\#$ for some object $U$
of $\mathcal{C}$. Then $j_\mathcal{F} : \Sh(\mathcal{C})/\mathcal{F}
\to \Sh(\mathcal{C})$ constructed in
Lemma \ref{lemma-localize-topos}
agrees with the morphism of topoi
$j_U : \Sh(\mathcal{C}/U) \to \Sh(\mathcal{C})$
constructed in
Section \ref{section-localize}
via the identification
$\Sh(\mathcal{C}/U) = \Sh(\mathcal{C})/h_U^\#$
of
Lemma \ref{lemma-essential-image-j-shriek}.

\label{lemma-push-down-quasi-affine}
Let $\pi : X \to Y$ be a finite surjective morphism of schemes.
Assume that $X$ is quasi-affine. If either
\begin{enumerate}
\item $\pi$ is finite locally free, or
\item $Y$ is an integral normal scheme
\end{enumerate}
then $Y$ is quasi-affine.

\label{lemma-check-torsion-on-affines}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is torsion free,
\item for $U \subset X$ affine open $\mathcal{F}(U)$
is a torsion free $\mathcal{O}(U)$-module.
\end{enumerate}

\label{theorem-descent}
The following conditions are equivalent.
\begin{enumerate}
\item[(a)] The morphism $f$ is a descent morphism for modules.
\item[(b)] The morphism $f$ is an effective descent morphism for modules.
\item[(c)] The morphism $f$ is universally injective.
\end{enumerate}

\label{lemma-abelian-variety-smooth}
Let $k$ be a field. Let $A$ be an abelian variety over $k$.
Then $A$ is smooth over $k$.

\label{lemma-faithful}
If $f : X \to S$ is surjective, then the functor
(\ref{equation-descent-etale}) is faithful.

\label{lemma-noetherian-zariski-jacobson-complement}
Let $(A, I)$ be a Zariski pair with $A$ Noetherian. Let $f \in I$.
Then $A_f$ is a Jacobson ring.

\label{lemma-characterize-effective-Cartier-divisor}
Let $S$ be a scheme.
Let $D \subset S$ be a closed subscheme.
The following are equivalent:
\begin{enumerate}
\item The subscheme $D$ is an effective Cartier divisor on $S$.
\item For every $x \in D$ there exists an affine open neighbourhood
$\Spec(A) = U \subset S$ of $x$ such that
$U \cap D = \Spec(A/(f))$ with $f \in A$ a nonzerodivisor.
\end{enumerate}

\label{lemma-intersection-number-integer}
In the situation of Definition \ref{definition-intersection-number}
the intersection number
$(\mathcal{L}_1 \cdots \mathcal{L}_d \cdot Z)$
is an integer.

\label{lemma-descending-property-quasi-compact-immersion}
The property $\mathcal{P}(f) =$``$f$ is a quasi-compact immersion''
is fpqc local on the base.

\label{lemma-quasi-regular-ideal-finite-projective}
Let $I \subset R$ be a quasi-regular ideal of a ring.
Then $I/I^2$ is a finite projective $R/I$-module.

\label{lemma-characterize-strict-general}
Let $\mathcal{A}$ be an abelian category.
Let $f : A \to B$ be a morphism of filtered objects of $\mathcal{A}$.
The following are equivalent
\begin{enumerate}
\item $f$ is strict,
\item the morphism $\Coim(f) \to \Im(f)$ of
Lemma \ref{lemma-coim-im-map}
is an isomorphism.
\end{enumerate}

\label{lemma-formally-smooth-finite-type}
Let $A \to B$ be a finite type ring map with $A$ Noetherian.
Let $\mathfrak q \subset B$ be a prime ideal lying over
$\mathfrak p \subset A$. The following are equivalent
\begin{enumerate}
\item $A \to B$ is smooth at $\mathfrak q$, and
\item $A_\mathfrak p \to B_\mathfrak q$ is formally smooth in
the $\mathfrak q$-adic topology.
\end{enumerate}

\label{lemma-integral-over-henselian-pair}
Let $(A, I)$ be a henselian pair and let $A \to B$ be an integral ring
map. Then $(B, IB)$ is a henselian pair.

\label{lemma-etale-on-fiber}
Consider a commutative diagram of morphisms of schemes
$$
\xymatrix{
U' \ar[r] \ar[d] & V' \ar[d] \\
U \ar[r] & V
}
$$
with \'etale vertical arrows and a point $v' \in V'$ mapping to $v \in V$.
Then the morphism of fibres $U'_{v'} \to U_v$ is \'etale.
